import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv(h):
    return np.convolve(h, h)


def construct(budget_seconds, start):
    """
    Improve C via a smooth bump family + local gradient-free refinement.

    Key idea: the optimum f has a smooth, unimodal-ish shape. Instead of
    coordinate descent on many heights (slow, noisy), parameterise f by a
    few shape parameters, optimise them, then refine the heights by
    coordinate descent on the residual.
    """
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(7)

    # Start from provided solution if valid
    base_h = None
    if start is not None:
        h = np.asarray(start, dtype=float).ravel()
        if h.size >= 1 and np.all(np.isfinite(h)) and h.sum() > 0 and np.all(h >= 0):
            base_h = np.maximum(h, 0.0)
            base_h = base_h / base_h.sum()

    # Build a fine-grid parametric family: symmetric-ish bump on [-.25,.25]
    # f(x) ~ exp(a*x^2 + b*|x| ...); try a few shapes and pick best.
    N = 2000
    i = np.arange(N)
    x = -0.25 + (i + 0.5) / N

    def build(params):
        a, b, c = params
        # symmetric part (a*x^2) + asymmetric (b*x) + cos bump (c)
        h = np.exp(a * x * x + b * x) * (1.0 + c * np.cos(4 * np.pi * x))
        return np.maximum(h, 0.0)

    best_C = np.inf
    best_h = None
    best_p = np.array([0.0, 0.0, 0.0])

    # coarse random/grid search over parameters
    candidates = []
    for a in np.linspace(-50, 5, 12):
        for b in np.linspace(-30, 30, 7):
            for c in (-0.9, -0.5, 0.0, 0.5):
                candidates.append((a, b, c))
    rng.shuffle(candidates)

    for p in candidates:
        if time.process_time() >= deadline:
            break
        h = build(p)
        if h.sum() <= 0:
            continue
        c = _C(h)
        if c < best_C:
            best_C = c
            best_h = h.copy()
            best_p = np.array(p, dtype=float)

    # local refinement of parameters (coordinate + random)
    if best_h is not None:
        p = best_p.copy()
        step = 1.0
        while time.process_time() < deadline and step > 1e-4:
            improved = False
            for k in range(3):
                for d in (step, -step):
                    if time.process_time() >= deadline:
                        break
                    q = p.copy()
                    q[k] += d
                    h = build(q)
                    if h.sum() <= 0:
                        continue
                    c = _C(h)
                    if c < best_C - 1e-12:
                        best_C = c
                        best_h = h.copy()
                        p = q
                        improved = True
            if not improved:
                step *= 0.5
        # random perturbation restarts
        while time.process_time() < deadline:
            q = p + rng.normal(0, 0.5, size=3)
            h = build(q)
            if h.sum() <= 0:
                continue
            c = _C(h)
            if c < best_C - 1e-9:
                best_C = c
                best_h = h.copy()
                p = q
            else:
                break

    # If base_h (from start) is better, keep it
    if base_h is not None:
        cb = _C(base_h)
        if cb < best_C:
            best_C = cb
            best_h = base_h.copy()

    if best_h is None:
        return np.ones(50) / 50.0

    # Now refine heights of best_h by coordinate descent on residual
    h = best_h / best_h.sum()
    N = len(h)
    step = 0.02

    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(N)
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = h[i]
            best_local = None
            best_local_c = best_C
            for delta in (step, -step, 0.5 * step, -0.5 * step):
                nv = old + delta
                if nv < 0:
                    continue
                h[i] = nv
                s = h.sum()
                if s <= 0:
                    continue
                c = 2.0 * N * np.max(np.convolve(h, h)) / (s * s)
                if c < best_local_c - 1e-14:
                    best_local_c = c
                    best_local = nv
            if best_local is not None:
                h[i] = best_local
                best_C = best_local_c
                improved = True
            else:
                h[i] = old
        if not improved:
            step *= 0.5
            if step < 1e-7:
                break

    # final normalise
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = best_h
    else:
        h = h / h.sum()

    # Also try upsampling the best parametric solution slightly for finer resolution
    return h

