def _profile(params, N):
    # params: aL, aR, gap, offset
    aL, aR, gap, off = params
    x = np.linspace(-0.5, 0.5, N)
    h = np.where(x < 0, np.exp(aL * (x + off)), np.exp(aR * (x + off)))
    # central gap: zero out a symmetric band of width gap
    if gap > 0:
        h = np.where(np.abs(x) < gap * 0.5, 0.0, h)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    N = 200
    best = None
