        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            sc = _C(s)
            if sc < bestC:
                best = s.copy()
                bestC = sc

    # Structured asymmetric exponential search
    bounds = [(-6.0, 6.0), (-6.0, 6.0), (0.0, 0.6), (-0.3, 0.3)]

    def obj(p):
        return _C(_profile(p, N))

    try:
        de = differential_evolution(obj, bounds, maxiter=40, popsize=12,
                                    tol=1e-6, seed=7, polish=True,
                                    init='latinhypercube')
        if de.fun < bestC:
            bestC = de.fun
            best = _profile(de.x, N)
    except Exception:
        pass

    # Local polish on parameters
    if time.process_time() < deadline and best is not None:
        try:
            # recover params roughly via another minimize from de.x if available
            pass
        except Exception:
            pass

    # Short coordinate refinement on the best profile
    if best is None:
        x = np.linspace(-1, 1, N)
        best = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05
        bestC = _C(best)

    h = best.copy()
    C = bestC
    rng = np.random.default_rng(999)
    step = 0.1
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(len(h))
        for i in idx:
            if time.process_time() >= deadline:
