import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    """Linearly interpolate heights h (length M) onto N points."""
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _refine(h, C, deadline, rng):
    """Coordinate descent on exact C with multiplicative and additive moves."""
    h = h.copy()
    step = 0.2
    mean = max(h.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(len(h))
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = h[i]
            # multiplicative moves
            for fac in (1.0 + step, 1.0 - step):
                h[i] = max(0.0, old * fac)
                c = _C(h)
                if c < C - 1e-15:
                    C = c
                    old = h[i]
                    improved = True
                else:
                    h[i] = old
            # additive moves
            for d in (step * mean, -step * mean):
                h[i] = max(0.0, old + d)
                c = _C(h)
                if c < C - 1e-15:
                    C = c
                    old = h[i]
                    improved = True
                else:
                    h[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-5:
                break
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(12345)

    # Base seed: use start if available, else a triangle bump.
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
        else:
            seed = None
    else:
        seed = None

    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Try several resolutions, refining each.
    for N in (100, 200, 400):
        if time.process_time() >= deadline:
            break
        h = _interp_to(seed, N)
        C = _C(h)
        h, C = _refine(h, C, deadline, rng)
        if C < bestC:
            bestC = C
            best = h.copy()

    # If time remains, continue refining the best at its own resolution.
    if time.process_time() < deadline:
        h, C = _refine(best, bestC, deadline, rng)
        if C < bestC:
            bestC = C
            best = h.copy()

    return np.asarray(best, dtype=float)

