    if s <= 0:
        return np.inf
    return 2.0 * N * float(np.max(np.convolve(h, h))) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(2024)

    # Candidate pool (h, C, N)
    pool = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            pool.append((s.copy(), _C(s, len(s)), len(s)))

    best_h = pool[0][0].copy() if pool else np.ones(50)
    best_C = pool[0][1] if pool else _C(best_h, len(best_h))

    def consider(h):
        nonlocal best_h, best_C
        h = np.asarray(h, dtype=float)
        if h.sum() <= 0:
            return
        c = _C(h, len(h))
        if c < best_C - 1e-14:
            best_C = c
            best_h = h.copy()

    # Multi-scale refinement: try several N, resample best_h, then coordinate descent.
    Ns = [50, 100, 200, 400, 800, 1200, 2000]
    # ensure start's N is included
    if start is not None:
        Ns = sorted(set(Ns + [len(np.asarray(start).ravel())]))

    for N in Ns:
        if time.process_time() >= deadline:
            break
        # resample best_h to N via linear interpolation
        old = best_h
        if len(old) != N:
            xo = (np.arange(len(old)) + 0.5) / len(old)
            xn = (np.arange(N) + 0.5) / N
            h = np.interp(xn, xo, old)
        else:
            h = old.copy()
        h = np.maximum(h, 0.0)
        if h.sum() <= 0:
            h = np.ones(N)
        C = _C(h, N)

        # coordinate descent with multiplicative and additive steps
        step = 0.08
        while time.process_time() < deadline and step > 1e-5:
            improved = False
            idx = rng.permutation(N)
            for i in idx:
                if time.process_time() >= deadline:
                    break
                old_v = h[i]
                # try multiplicative
                for fac in (1.0 + step, 1.0 - step):
                    h[i] = max(0.0, old_v * fac)
                    c = _C(h, N)
                    if c < C - 1e-15:
                        C = c
                        old_v = h[i]
                        improved = True
                    else:
                        h[i] = old_v
                # try additive proportional to current scale
                scale = h.mean() if h.mean() > 0 else 1.0
                for d in (step * scale, -step * scale):
                    h[i] = max(0.0, old_v + d)
                    c = _C(h, N)
                    if c < C - 1e-15:
                        C = c
                        old_v = h[i]
                        improved = True
                    else:
                        h[i] = old_v
            if not improved:
                step *= 0.55
            if C < best_C - 1e-14:
                best_C = C
                best_h = h.copy()
                consider(h)

    return np.asarray(best_h, dtype=float)

