def _softmax_obj(h, beta):
    """Return J and analytic gradient. J = (1/beta) log sum exp(beta*conv) / S^2."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)  # length 2N-1
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    # J = (1/beta) * logZ / S^2
    J = logZ / (beta * S * S)
    # p_k = softmax
    p = e / Z
    # d/dh_i of sum_k p_k * conv_k. conv_k = sum_j h_j h_{k-j}
    # d conv_k / d h_i = 2 h_{k-i} (with valid indices)
    # grad_conv_i = 2 * sum_k p_k * h_{k-i}
    # Compute via correlation: grad_conv = 2 * correlate(p, h) style
    # sum_k p_k h_{k-i}, k ranges 0..2N-2, h index k-i in 0..N-1
    # This is cross-correlation of p with h at lag i.
    # Use np.convolve(p, h[::-1]) and slice.
    corr = np.convolve(p, h[::-1])  # length 3N-2
    # corr[i + (N-1)] = sum_k p_k h_{k-i}? Let's verify: conv(p, h_rev)[m] = sum_j p[j] h_rev[m-j]
    # h_rev[t] = h[N-1-t]. So = sum_j p[j] h[N-1-(m-j)] = sum_j p[j] h[N-1-m+j]
    # want sum_k p_k h[k-i]: set N-1-m+j = k-i with j=k => N-1-m = -i => m = N-1+i. yes.
    grad_conv = 2.0 * corr[N - 1: N - 1 + N]
    # dJ/dh_i = (1/(beta*S^2)) * (1/Z) * sum_k e_k * beta * dconv_k/dh_i - 2*J/S
    # = (1/(S^2)) * sum_k p_k * dconv_k/dh_i - 2*J/S
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


