    """Subgradient of C w.r.t. h (using argmax of conv)."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N)
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    M = conv[k]
    # dM/dh_i = 2*h[k-i] where valid
    gM = np.zeros(N)
    for i in range(N):
