    # fixed large beta, and gradient-descent L-BFGS on the smoothed max
    # is far more effective than coordinate descent near the optimum.
    betas = [200.0, 800.0, 3000.0, 12000.0, 50000.0]
    for N in [len(best), 800, 1500]:
        if time.process_time() >= deadline:
            break
        h, c = _refine_softmax(best, N, deadline, betas)
        if c < bestC:
            bestC = c
            best = h.copy()

    # Final exact-C L-BFGS polish using subgradient of C at current argmax.
    # Repeatedly re-evaluate argmax and run a few L-BFGS steps — this
    # directly minimizes the exact nonsmooth objective rather than a
    # smooth surrogate, fine-tuning the location of the maximum.
