    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: N - 1 + N]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _adam_polish(h, deadline, max_iter=3000, lr=0.01):
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = len(h)
    if N == 0 or h.sum() <= 0:
        return h
    x = np.log(np.maximum(h, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    best = h.copy()
    bestC = _C(h)
    for t in range(1, max_iter + 1):
        if time.process_time() >= deadline:
            break
        hh = np.exp(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = np.convolve(hh, hh)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        g = np.zeros(N)
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        g[lo:hi + 1] = 2.0 * hh[k - np.arange(lo, hi + 1)]
        g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
        gl = g * hh
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        hh2 = np.exp(x)
        c2 = _C(hh2)
        if c2 < bestC:
