def _refine_softmax(h, N, deadline, betas):
    h = _interp_to(h, N)
    h = h / max(h.max(), 1e-12)
    state = {'best': h.copy(), 'bestC': _C(h)}

    for beta in betas:
        if time.process_time() >= deadline:
            break

        def fun(x, _beta=beta):
            return _softmax_obj(x, _beta)

