    """Exact-C coordinate descent polish."""
    h = h.copy()
    N = len(h)
    curC = _C(h)
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        S = h.sum()
        if S <= 0:
            break
        hs = h / S
        conv = np.convolve(hs, hs)
        k = int(np.argmax(conv))
        gM = np.zeros(N)
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        for i in range(lo, hi + 1):
            gM[i] = 2.0 * hs[k - i]
        g = 2.0 * N * gM
        step = 0.01 * (np.abs(h).max() + 1e-12)
        improved = False
        for _ls in range(20):
            hn = np.maximum(0.0, h - step * g)
            if hn.sum() <= 0:
                step *= 0.5
