    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: N - 1 + N]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _active_subgrad(h, tol=1e-4):
    """Average subgradient of exact C over all near-active convolution knots."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = np.convolve(h, h)
    cmax = conv.max()
    C = 2.0 * N * cmax / (S * S)
    active = np.where(conv >= cmax * (1.0 - tol))[0]
    g = np.zeros(N)
    for k in active:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        g[lo:hi + 1] += 2.0 * h[k - np.arange(lo, hi + 1)]
    g /= len(active)
    g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
    return C, g


def _bb_projected(h, deadline, max_iter=400):
    """Projected gradient with Barzilai-Borwein step + backtracking on exact C."""
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = len(h)
    if N == 0 or h.sum() <= 0:
        return h
    C, g = _active_subgrad(h)
    best = h.copy()
    bestC = C
    # initial BB step
    alpha = 1.0 / (np.linalg.norm(g) + 1e-12)
    alpha = min(alpha, 1e-2)
    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        # projected step
        h_new = np.maximum(0.0, h - alpha * g)
        s = h_new.sum()
        if s <= 0:
            alpha *= 0.5
            continue
        C_new, g_new = _active_subgrad(h_new)
        # backtracking
        bt = 0
        while C_new > C - 1e-15 and bt < 20:
            alpha *= 0.5
            h_new = np.maximum(0.0, h - alpha * g)
            s = h_new.sum()
            if s <= 0:
                break
            C_new, g_new = _active_subgrad(h_new)
            bt += 1
        if s <= 0 or C_new > C:
            break
        # BB step from secant
        d = h_new - h
        y = g_new - g
        sy = float(np.dot(d, y))
        if sy > 1e-20:
            alpha = float(np.dot(d, d)) / sy
        else:
            alpha *= 0.7
        alpha = min(max(alpha, 1e-8), 1e-1)
        h = h_new
        C = C_new
        g = g_new
        if C < bestC:
            bestC = C
            best = h.copy()
    return best


def _coord_descent(hh, C, deadline, step0=0.02):
    rng = np.random.default_rng(12345)
    hh = hh.copy()
    step = step0
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(len(hh))
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = hh[i]
            for fac in (1.0 + step, 1.0 - step):
                hh[i] = max(0.0, old * fac)
                cc = _C(hh)
                if cc < C - 1e-15:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
            for d in (step * mean, -step * mean):
                hh[i] = max(0.0, old + d)
                cc = _C(hh)
                if cc < C - 1e-15:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-6:
                break
    return hh, C


