def _peak_grad(h):
    """Gradient of exact C w.r.t. h (subgradient at argmax)."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N)
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    C = 2.0 * N * conv[k] / (S * S)
    g = np.zeros(N)
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
