    hh = h.copy()
    step = 0.02
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(len(hh))
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = hh[i]
            best_local = old
            best_c = C
            for fac in (1.0 + step, 1.0 - step):
                nv = max(0.0, old * fac)
                hh[i] = nv
                cc = _C(hh)
                if cc < best_c - 1e-15:
                    best_c = cc
                    best_local = nv
            for d in (step * mean, -step * mean):
                nv = max(0.0, best_local + d)
                hh[i] = nv
                cc = _C(hh)
                if cc < best_c - 1e-15:
                    best_c = cc
                    best_local = nv
            hh[i] = best_local
            if best_c < C - 1e-15:
                C = best_c
                improved = True
        if not improved:
            step *= 0.6
            if step < 1e-7:
                break
    return hh, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    rng = np.random.default_rng(12345)

    # Load start seed
    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = np.maximum(s, 0.0)
            if s.sum() > 0:
                seed = s / s.sum()

    if seed is None:
        x = np.linspace(-1.0, 1.0, 200)
        seed = np.maximum(0.0, 1.0 - np.abs(x) ** 2) + 0.02
        seed /= seed.sum()

    best = seed.copy()
    bestC = _C(best)

    if _HAVE_SCIPY:
        # Multi-resolution: try a few N values, keeping the best by exact C.
        # Start from the current best (possibly upsampled), refine with LSE surrogate.
        Ns = [len(seed)]
        for N in (500, 1000, 2000, 4000, 8000):
            if N not in Ns:
                Ns.append(N)
        betas = [500.0, 2000.0, 8000.0, 30000.0, 120000.0]

        for N in Ns:
            if time.process_time() >= deadline:
                break
            h = _interp_to(best, N)
            mx = h.max()
            if mx > 0:
                h = h / mx
            hb, hc = _refine_sm(h, betas, deadline)
            if hc < bestC - 1e-12:
                bestC = hc
                best = hb.copy()

    # Coordinate polish on best
    if time.process_time() < deadline:
        hh, C = _coord_polish(best, bestC, deadline, rng)
        if C < bestC:
            bestC = C
            best = hh

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

