import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _polish(h, deadline, betas):
    best = h.copy()
    bestC = _C(h)
    xcur = h.copy()
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        try:
            res = minimize(fun, xcur, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 1500, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-13})
            xcur = res.x
        except StopIteration:
            xcur = state['best']
            break
        c = _C(xcur)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xcur.copy()
        if state['bestC'] < bestC:
            bestC = state['bestC']
            best = state['best'].copy()
            xcur = best.copy()
    return best, bestC


