            return _pnorm_obj(x, _p, _M0)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(best),
                           callback=cb,
