                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < bestC:
            bestC = c
            best = xf.copy()
        else:
            best = state['best'].copy()
            bestC = state['bestC']
    return best, bestC


