    return J, grad


def _gauss_smooth(h, sigma):
    """Light Gaussian smoothing to remove knot artifacts."""
    if sigma <= 0:
        return h
    r = int(max(1, round(3 * sigma)))
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _polish(h, deadline, betas, smooth_sigma=0.0):
    best = h.copy()
    bestC = _C(h)
    xcur = h.copy()
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
