            best = state['best'].copy()
            xcur = best.copy()
    return best, bestC


def _exact_cd(h, deadline, step0=0.05):
    """Coordinate descent with multiplicative & additive moves on exact C."""
    hh = h.copy()
    N = len(hh)
    C = _C(hh)
    rng = np.random.default_rng(999)
    step = step0
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(N)
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = hh[i]
            for fac in (1.0 + step, 1.0 - step):
                hh[i] = max(0.0, old * fac)
                cc = _C(hh)
                if cc < C - 1e-15:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
            for d in (step * mean, -step * mean):
                hh[i] = max(0.0, old + d)
                cc = _C(hh)
                if cc < C - 1e-15:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-7:
                break
