def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 200
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Downsample start to K control points and re-fit: this removes high-frequency
    # knot artifacts from the start's step function that inflate the max.
    K = 40
    xp = np.linspace(0.0, 1.0, len(seed))
    xq = np.linspace(0.0, 1.0, K)
    c0 = np.maximum(np.interp(xq, xp, seed), 0.0)

    N = 3000

    # Phase 1: smooth the start and re-optimize controls at low N.
    h_smooth = np.interp(np.linspace(0, 1, N), xp, seed)
    h_smooth = _gauss_smooth(h_smooth, sigma=3.0)
    h_smooth = np.maximum(h_smooth, 0.0)
    # Re-fit control grid by averaging smoothed signal into K bins.
    bins = np.linspace(0, N, K + 1).astype(int)
    c_sm = np.array([h_smooth[bins[i]:bins[i + 1]].mean() for i in range(K)])
    if c_sm.sum() > 0:
        c0 = c_sm

    # Build a low-N problem to optimize controls cheaply.
    NL = 600
    xpL = np.linspace(0, 1, K)
    xqL = np.linspace(0, 1, NL)

    def ctrl_to_h(c):
        return np.maximum(np.interp(xqL, xpL, c), 0.0)

    def obj_ctrl(c, beta):
        h = ctrl_to_h(c)
        J, g = _softmax_obj(h, beta)
        idx = np.clip(np.searchsorted(xpL, xqL) - 1, 0, K - 2)
        t = np.clip((xqL - xpL[idx]) / (xpL[idx + 1] - xpL[idx]), 0.0, 1.0)
        gx = np.zeros(K)
        np.add.at(gx, idx, g * (1.0 - t))
        np.add.at(gx, idx + 1, g * t)
        return J, gx

    state = {'best': c0.copy(), 'bestC': _C(ctrl_to_h(c0))}
    for beta in [300.0, 1500.0, 8000.0, 40000.0]:
        if time.process_time() >= deadline:
            break

        def fun(x, _b=beta):
            return obj_ctrl(x, _b)

        def cb(xk):
            c = _C(ctrl_to_h(xk))
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        try:
            minimize(fun, state['best'].copy(), jac=True, method='L-BFGS-B',
                      bounds=[(0.0, None)] * K, callback=cb,
                      options={'maxiter': 600, 'maxfun': 12000,
                               'ftol': 1e-16, 'gtol': 1e-13})
        except StopIteration:
            pass

    # Phase 2: upsample smooth solution to N and do softmax continuation at high res.
    h_hi = _interp_to(state['best'], N)
    h_hi = np.maximum(h_hi, 0.0)
    if h_hi.sum() <= 0:
        h_hi = _interp_to(seed, N)
