import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _polish(h, deadline, betas):
    """Multi-beta softmax L-BFGS on the full N-length vector."""
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': 1500, 'maxfun': 15000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < bestC:
            bestC, best = c, xf.copy()
        else:
            best, bestC = state['best'].copy(), state['bestC']
    return best, bestC


def _exact_cd(h, deadline, iters=300):
    """Coordinate descent on exact C with line search on the argmax knot."""
    h = h.copy()
    N = len(h)
    curC = _C(h)
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        S = h.sum()
        if S <= 0:
            break
        hs = h / S
        conv = np.convolve(hs, hs)
        k = int(np.argmax(conv))
        gM = np.zeros(N)
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        gM[lo:hi + 1] = 2.0 * hs[k - np.arange(lo, hi + 1)]
        g = 2.0 * N * gM
        step = 0.02 * (np.abs(h).max() + 1e-12)
        improved = False
        for _ls in range(30):
            hn = np.maximum(0.0, h - step * g)
            if hn.sum() <= 0:
                step *= 0.5
                continue
            cn = _C(hn)
            if cn < curC - 1e-15:
                h, curC = hn, cn
                improved = True
                break
            step *= 0.5
        if not improved:
            break
    return h, curC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
        else:
            seed = None
    else:
        seed = None

    if seed is None:
        x = np.linspace(-1, 1, 50)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Try several resolutions around the seed's current size; the exact-C
    # landscape has better local minima at moderate N.  We upsample/downsample
    # the start and polish at each N, keeping the best.
    N0 = len(seed)
    Ns = sorted(set([N0, 400, 800, 1200, 1800, 2500, 3500]))
    Ns = [n for n in Ns if 20 <= n <= 30000]

    betas = [100.0, 500.0, 2000.0, 8000.0, 30000.0]

    for Nn in Ns:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, Nn)
        if h.sum() <= 0:
            h = np.ones(Nn)
        h = h / h.max()
        hb, cb = _polish(h, deadline, betas)
        if cb < bestC:
            best, bestC = hb.copy(), cb
        # exact-C polish on this resolution
        hc, cc = _exact_cd(hb, deadline)
        if cc < bestC:
            best, bestC = hc.copy(), cc

    # Final exact-C coordinate descent polish on the best.
    if time.process_time() < deadline:
        hc, cc = _exact_cd(best, deadline, iters=400)
        if cc < bestC:
            best, bestC = hc.copy(), cc

    return np.asarray(best, dtype=float)

