def _pnorm_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    cpos = np.maximum(conv, 0.0)
    cp = cpos ** (p - 1)
    sp = float(np.sum(cpos ** p))
    if sp <= 0:
        return 1e18, np.zeros(N)
    spow = sp ** (1.0 / p)
    J = spow / (S * S)
    # d/dh of (sum conv^p)^(1/p) = (sum conv^p)^(1/p-1) * conv^(p-1) * dconv/dh
    w = sp ** (1.0 / p - 1.0) * cp  # weight on conv
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: N - 1 + N]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


