    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N)
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    C = 2.0 * N * conv[k] / (S * S)
    g = np.zeros(N)
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
    g[lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
    return g


