    grad_conv = 2.0 * corr[N - 1: N - 1 + N]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _refine_sm(h, betas, deadline):
    state = {'best': h.copy(), 'bestC': _C(h)}
    for beta in betas:
        if time.process_time() >= deadline:
            break

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-13})
            xf = res.x
            c = _C(xf)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xf.copy()
        except StopIteration:
            pass
    return state['best'], state['bestC']


def _peak_grad(h):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N)
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    C = 2.0 * N * conv[k] / (S * S)
    g = np.zeros(N)
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
    g[lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
    return g


def _adam_polish(h, deadline, max_iter=4000, lr=0.005):
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = len(h)
    if N == 0 or h.sum() <= 0:
        return h
    x = np.log(np.maximum(h, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    best = h.copy()
    bestC = _C(h)
    for t in range(1, max_iter + 1):
        if time.process_time() >= deadline:
            break
        hh = np.exp(x)
        g = _peak_grad(hh)
        gl = g * hh
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        hh2 = np.exp(x)
        c2 = _C(hh2)
        if c2 < bestC:
            bestC = c2
            best = hh2.copy()
    return best


def _coord_polish(hh, C, deadline):
    rng = np.random.default_rng(999)
    step = 0.02
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(len(hh))
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = hh[i]
            for fac in (1.0 + step, 1.0 - step):
                hh[i] = max(0.0, old * fac)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
            for d in (step * mean, -step * mean):
                hh[i] = max(0.0, old + d)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-7:
                break
    return hh, C


def _stretch(h):
    """Crop to nonzero core and stretch to full length."""
    h = np.asarray(h, dtype=float)
    nz = np.where(h > 1e-12)[0]
    if nz.size < 2:
        return None
    i0, i1 = int(nz[0]), int(nz[-1])
    core = h[i0:i1 + 1]
    if core.size < 2:
        return None
    stretched = _interp_to(core, len(h))
    m = stretched.max()
    if m <= 0:
        return None
    return stretched / m


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
        else:
            seed = None
    else:
        seed = None

    if seed is None:
        x = np.linspace(-1, 1, 50)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Phase 0: try stretching the nonzero core to the full interval.
    if time.process_time() < deadline:
        st = _stretch(best)
        if st is not None:
            cs = _C(st)
            if cs < bestC:
                bestC = cs
                best = st.copy()

    # Phase 1: softmax continuation at several N.
    base_N = len(best)
    N_list = []
    for f in (1.0, 2.0, 0.5):
        n = int(round(base_N * f))
        n = max(50, min(30000, n))
        if n not in N_list:
            N_list.append(n)
    betas = [1000.0, 4000.0, 16000.0, 64000.0, 256000.0]
    for N in N_list:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, N)
        if h.sum() <= 0:
            continue
        h = h / max(h.max(), 1e-12)
        hb, hc = _refine_sm(h, betas, deadline)
        if hc < bestC:
            bestC = hc
            best = hb.copy()

    # Phase 2: Adam in log-space.
    if time.process_time() < deadline:
        polished = _adam_polish(best, deadline, max_iter=4000, lr=0.004)
        cp = _C(polished)
        if cp < bestC:
            bestC = cp
            best = polished.copy()

    # Phase 3: coordinate polish on exact C.
    if time.process_time() < deadline:
        hh, C = _coord_polish(best.copy(), bestC, deadline)
        if C < bestC:
            bestC = C
            best = hh.copy()

    return np.asarray(best, dtype=float)

