    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _sym(h):
    return 0.5 * (h + h[::-1])


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _polish_lbfgs_sym(h, deadline, n_restarts=2):
    """L-BFGS polish with symmetry projection after every iteration."""
    best = _sym(h.copy())
    bestC = _C(best)
    betas = [50.0, 200.0, 800.0, 3000.0]
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            xs = _sym(xk)
