            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xs.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = _sym(res.x)
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < bestC:
            bestC = c
            best = xf.copy()
        else:
            best = state['best'].copy()
            bestC = state['bestC']
    return best, bestC


def _adam_logspace_sym(best, bestC, deadline):
    if time.process_time() >= deadline:
        return best, bestC
    hh = _sym(np.maximum(best.copy(), 0.0))
    N = len(hh)
    x = np.log(np.maximum(hh, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    lr = 0.005
    bestC2 = bestC
    best2 = hh.copy()
    for t in range(1, 5000):
        if time.process_time() >= deadline:
            break
        hcur = _sym(np.exp(x))
        S = hcur.sum()
        if S <= 0:
            break
        conv = np.convolve(hcur, hcur)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        g = np.zeros(N)
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        for j in range(lo, hi + 1):
            g[j] = 2.0 * hcur[k - j]
        g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
        gl = g * hcur
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        if t % 20 == 0:
            hc = _sym(np.exp(x))
            cc = _C(hc)
            if cc < bestC2:
                bestC2 = cc
                best2 = hc.copy()
    if bestC2 < bestC:
        return best2, bestC2
    return best, bestC


