    for Nn in [1200, 2000]:
        if time.process_time() >= deadline:
            break
        h = _interp_to(seed, Nn)
        if h.sum() <= 0:
            h = np.ones(Nn)
        h = h / h.max()
        h = _sym(h)
        hb, cb = _polish_lbfgs_sym(h, deadline)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
        hb2, cb2 = _adam_logspace_sym(hb, cb, deadline)
        if cb2 < bestC:
            bestC = cb2
            best = hb2.copy()
        # final polish
        if time.process_time() < deadline:
            hb3, cb3 = _polish_lbfgs_sym(best, deadline)
            if cb3 < bestC:
                bestC = cb3
                best = hb3

    return np.asarray(best, dtype=float)

