def _plateau_grad(h):
    """Gradient of exact C, averaged over all knots within tiny rel of max."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N), np.inf
    conv = np.convolve(h, h)
    cmax = conv.max()
    C = 2.0 * N * cmax / (S * S)
    thr = cmax - 1e-7 * cmax
    active = np.where(conv >= thr)[0]
    g = np.zeros(N)
    for k in active:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        g[lo:hi + 1] += h[k - np.arange(lo, hi + 1)]
    g = g / len(active)
    g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
    return g, C


def _softmax_obj(h, beta):
