def _lbfgs(h, betas, deadline):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
            c = _C(xf)
            if c < bestC:
                bestC = c
                best = xf.copy()
        except StopIteration:
            pass
        if state['bestC'] < bestC:
            bestC = state['bestC']
            best = state['best'].copy()
    return best, bestC


def _adam(h, deadline, n_iter=20000, lr0=0.004, lr1=0.0002):
    hh = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = len(hh)
    if N == 0 or hh.sum() <= 0:
        return hh, _C(hh)
    x = np.log(np.maximum(hh, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    best = hh.copy()
    bestC = _C(hh)
    for t in range(1, n_iter + 1):
        if time.process_time() >= deadline:
            break
        lr = lr0 + (lr1 - lr0) * (t - 1) / max(1, n_iter - 1)
        hcur = np.exp(x)
        g, C = _plateau_grad(hcur)
        gl = g * hcur
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        if t % 10 == 0:
            hc = np.exp(x)
            cc = _C(hc)
            if cc < bestC:
                bestC = cc
                best = hc.copy()
    return best, bestC


def _coord(hh, C, deadline):
    rng = np.random.default_rng(7)
    step = 0.02
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        for i in rng.permutation(len(hh)):
            if time.process_time() >= deadline:
                break
            old = hh[i]
            for fac in (1.0 + step, 1.0 - step):
                hh[i] = max(0.0, old * fac)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
            for d in (step * mean, -step * mean):
                hh[i] = max(0.0, old + d)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-7:
                break
    return hh, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        x = np.linspace(-1, 1, 50)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Phase A: increase resolution (finer grid often lowers C).
    N0 = len(seed)
    Ns = sorted(set([N0, 2 * N0, 3 * N0, 1500, 3000]))
    Ns = [n for n in Ns if 50 <= n <= 30000]
    betas = [200.0, 1000.0, 4000.0, 16000.0]
    for N in Ns:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, N)
        if h.sum() <= 0:
            continue
        h = h / max(h.max(), 1e-12)
        hb, cb = _lbfgs(h, betas, deadline)
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    # Phase B: Adam in log-space with plateau-averaged gradient.
    if time.process_time() < deadline:
        hb, cb = _adam(best, deadline)
        if cb < bestC:
            bestC = cb
            best = hb

    # Phase C: coordinate polish on exact C.
    if time.process_time() < deadline:
        hb, cb = _coord(best.copy(), bestC, deadline)
        if cb < bestC:
            bestC = cb
            best = hb

    # Phase D: final L-BFGS touch-up.
    if time.process_time() < deadline:
        hb, cb = _lbfgs(best, [4000.0, 16000.0], deadline)
        if cb < bestC:
            bestC = cb
            best = hb

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0)):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(best),
                           callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < bestC:
            bestC = c
            best = xf.copy()
        else:
            best = state['best'].copy()
            bestC = state['bestC']
    return best, bestC


def _pnorm_obj(h, p, M0):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    u = np.maximum(conv / M0, 1e-300)
    up = u ** p
    T = up.sum()
    J = (T ** (1.0 / p)) * M0 / (S * S)
    dJ_dconv = (T ** (1.0 / p - 1.0)) * (u ** (p - 1.0)) / (S * S)
    corr = np.convolve(dJ_dconv, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _polish_pnorm(h, deadline, ps=(30.0, 60.0, 120.0, 250.0, 500.0, 1000.0,
                                    2000.0, 4000.0, 8000.0)):
    best = h.copy()
    bestC = _C(h)
    for p in ps:
        if time.process_time() >= deadline:
            break
        conv = np.convolve(best, best)
        M0 = float(np.max(conv))
        if M0 <= 0:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _p=p, _M0=M0):
            return _pnorm_obj(x, _p, _M0)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(best),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < bestC:
            bestC = c
            best = xf.copy()
        else:
            best = state['best'].copy()
            bestC = state['bestC']
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print(f"start C={bestC:.9f} N={len(best)}")

    # Multi-resolution: try larger N by interpolation, keeping best.
    # Larger N gives more freedom to shape the argmax region.
    Ns = []
    if len(seed) < 3000:
        Ns = [len(seed) * 2, len(seed) * 4, 3000, 6000]
    elif len(seed) < 6000:
        Ns = [len(seed), 6000, 9000]
    else:
        Ns = [len(seed)]
    Ns = [n for n in Ns if 1 <= n <= 30000]
    Ns = sorted(set(Ns))

    for N in Ns:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, N)
        if h.sum() <= 0:
            h = np.ones(N)
        h = h / h.max()
        hb, cb = _polish_lbfgs(h, deadline, betas=(200.0, 800.0, 3000.0, 8000.0))
        if cb < bestC:
            bestC = cb
            best = hb.copy()
            print(f"  N={N} lbfgs C={bestC:.9f}")
        # p-norm polish at this N
        if time.process_time() < deadline:
            hb, cb = _polish_pnorm(best, deadline,
                                   ps=(100.0, 400.0, 1500.0, 6000.0, 20000.0))
            if cb < bestC:
                bestC = cb
                best = hb.copy()
                print(f"  N={N} pnorm C={bestC:.9f}")

    # Final high-p polish at current N
    if time.process_time() < deadline:
        hb, cb = _polish_pnorm(best, deadline,
                               ps=(20000.0, 50000.0, 100000.0))
        if cb < bestC:
            bestC = cb
            best = hb.copy()
            print(f"final pnorm C={bestC:.9f}")

    print(f"end C={bestC:.9f} N={len(best)}")
