def _coordinate_polish(h, deadline, rng):
    """Exact-C coordinate descent with multiplicative + additive moves."""
    hh = h.copy()
    C = _C(hh)
    N = len(hh)
    step = 0.05
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(N)
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = hh[i]
            best_local = C
            best_val = old
            for fac in (1.0 + step, 1.0 - step):
                cand = max(0.0, old * fac)
                hh[i] = cand
                cc = _C(hh)
                if cc < best_local - 1e-15:
                    best_local = cc
                    best_val = cand
            for d in (step * mean, -step * mean):
                cand = max(0.0, old + d)
                hh[i] = cand
                cc = _C(hh)
                if cc < best_local - 1e-15:
                    best_local = cc
                    best_val = cand
            hh[i] = best_val
            if best_val != old:
                C = best_local
                improved = True
        if not improved:
            step *= 0.6
            if step < 1e-6:
                break
    return hh, C


