    # (or interpolate to 600 if seed is small).
    N = len(seed)
    if N < 200:
        N = 600
        h = _interp_to(seed, N)
    else:
        h = seed.copy()
    hmax = h.max()
    if hmax > 0:
        h = h / hmax

    if time.process_time() < deadline:
        hb, cb = _polish_lbfgs(h, deadline)
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    # Coordinate polish on exact C
    if time.process_time() < deadline:
        rng = np.random.default_rng(999)
        hh, C = _coordinate_polish(best, deadline, rng)
        if C < bestC:
            bestC = C
