import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _sym(h):
    return 0.5 * (h + h[::-1])


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _polish_lbfgs_sym(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0)):
    best = _sym(h.copy())
    bestC = _C(best)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            xs = _sym(xk)
            c = _C(xs)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xs.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = _sym(res.x)
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < bestC:
            bestC = c
            best = xf.copy()
        else:
            best = state['best'].copy()
            bestC = state['bestC']
    return best, bestC


def _adam_logspace_sym(best, bestC, deadline, lr=0.004, iters=6000):
    hh = _sym(np.maximum(best.copy(), 0.0))
    N = len(hh)
    x = np.log(np.maximum(hh, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    bestC2 = bestC
    best2 = hh.copy()
    for t in range(1, iters + 1):
        if time.process_time() >= deadline:
            break
        hcur = _sym(np.exp(x))
        S = hcur.sum()
        if S <= 0:
            break
        conv = np.convolve(hcur, hcur)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        g = np.zeros(N)
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        g[idx] = 2.0 * hcur[k - idx]
        g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
        gl = g * hcur
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        if t % 20 == 0:
            hc = _sym(np.exp(x))
            cc = _C(hc)
            if cc < bestC2:
                bestC2 = cc
                best2 = hc.copy()
    if bestC2 < bestC:
        return best2, bestC2
    return best, bestC


def _rand_perturb(h, rng, scale=0.15):
    """Random multiplicative perturbation preserving symmetry."""
    N = len(h)
    noise = np.exp(scale * rng.standard_normal(N))
    out = h * noise
    return _sym(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    rng = np.random.default_rng(12345)

    # Main experiment: refine at current resolution, then at higher resolutions.
    # Use multi-start random perturbations to escape local minima.
    resolutions = [len(seed)]
    for Nn in [1200, 1500, 2000]:
        if Nn not in resolutions:
            resolutions.append(Nn)

    for Nn in resolutions:
        if time.process_time() >= deadline:
            break
        base = _interp_to(best, Nn)
        if base.sum() <= 0:
            base = np.ones(Nn)
        base = base / base.max()
        base = _sym(base)
        # A few random restarts around the base
        n_restarts = 3 if Nn == len(seed) else 2
        local_best = base.copy()
        local_C = _C(local_best)
        for r in range(n_restarts):
            if time.process_time() >= deadline:
                break
            if r == 0:
                cand = base.copy()
            else:
                cand = _rand_perturb(base, rng, scale=0.08 + 0.05 * r)
            hb, cb = _polish_lbfgs_sym(cand, deadline)
            if cb < local_C:
                local_C = cb
                local_best = hb.copy()
            if time.process_time() < deadline:
                hb2, cb2 = _adam_logspace_sym(local_best, local_C, deadline)
                if cb2 < local_C:
                    local_C = cb2
                    local_best = hb2.copy()
        if local_C < bestC:
            bestC = local_C
            best = local_best.copy()

    # Final polish at original resolution (cheap) to make sure we hold best.
    if time.process_time() < deadline:
        hb, cb = _polish_lbfgs_sym(best, deadline)
        if cb < bestC:
            bestC = cb
            best = hb

    return np.asarray(best, dtype=float)

