    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _pnorm_obj(h, p, M0):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    u = np.maximum(conv / M0, 1e-300)
    up = u ** p
    T = up.sum()
    J = (T ** (1.0 / p)) * M0 / (S * S)
    dJ_dconv = (T ** (1.0 / p - 1.0)) * (u ** (p - 1.0)) / (S * S)
    corr = np.convolve(dJ_dconv, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _polish_pnorm(h, deadline, ps=(50.0, 100.0, 200.0, 400.0)):
    best = h.copy()
    bestC = _C(h)
    for p in ps:
        if time.process_time() >= deadline:
            break
        conv = np.convolve(best, best)
        M0 = float(np.max(conv))
        if M0 <= 0:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _p=p, _M0=M0):
            return _pnorm_obj(x, _p, _M0)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(best),
                           callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < bestC:
            bestC = c
            best = xf.copy()
        else:
            best = state['best'].copy()
            bestC = state['bestC']
    return best, bestC


def _active_set_obj(h):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    M = float(conv.max())
    tol = 1e-6 * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       callback=cb,
                       options={'maxiter': 3000, 'maxfun': 30000,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _stretch_core(h):
    hmax = h.max()
    if hmax <= 0:
        return h.copy()
    thr = 1e-8 * hmax
    nz = np.where(h > thr)[0]
    if nz.size == 0:
        return h.copy()
    i0, i1 = nz[0], nz[-1]
    core = h[i0:i1 + 1]
    N = len(h)
    out = _interp_to(core, N)
    m = out.max()
    if m > 0:
        out = out / m
    return out


def _smooth_quantile_obj(h, alpha, M0):
    """Smooth approximation of max via a 'quantile-like' softmax with exponent alpha."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    # Use softmax over conv but only relative to M0, normalized.
    z = alpha * (conv - M0) / M0
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    # Smooth max estimate
    Ms = M0 + (logZ - np.log(len(conv))) / alpha * M0
    J = 2.0 * N * Ms / (S * S)
    p = e / Z
    # dMs/dconv = p * M0 (since d/dconv of (conv-M0) is 1, scaled)
    # Actually Ms = M0 + (logZ - log L)/alpha * M0, dMs/dconv_i = M0 * p_i
    dJ_dconv = 2.0 * N * M0 * p / (S * S)
    corr = np.convolve(dJ_dconv, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 4.0 * N * Ms / (S * S * S)
    return J, grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # 1) Stretch nonzero core to full interval: this is the key structural move.
    if time.process_time() < deadline:
        stretched = _stretch_core(best)
        if stretched.sum() > 0:
            # Polish with p-norm increasing sequence
            hb, cb = _polish_pnorm(stretched, deadline, ps=(20.0, 50.0, 100.0, 200.0))
            if cb < bestC:
                bestC = cb
                best = hb.copy()
            # Then active set + more p-norm
            if time.process_time() < deadline:
                hb, cb = _active_set_polish(best, deadline)
                if cb < bestC:
                    bestC = cb
                    best = hb.copy()
            if time.process_time() < deadline:
                hb, cb = _polish_pnorm(best, deadline, ps=(400.0, 800.0, 1600.0))
                if cb < bestC:
                    bestC = cb
                    best = hb.copy()

    # 2) Also polish original seed to not lose ground.
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline)
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    # 3) Try different resolutions of the current best, polish, keep if improves.
    Ns = [800, 1200, 1600]
    for Nn in Ns:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, Nn)
        if h.sum() <= 0:
            continue
        h = h / h.max()
        hb, cb = _polish_pnorm(h, deadline, ps=(50.0, 200.0, 800.0))
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    # 4) Final active set polish at current resolution.
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline)
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
