def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0)):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       callback=cb,
                       options={'maxiter': 3000, 'maxfun': 30000,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Focused fine sweep around N~1100 with full polish per size.
    Ns = [1025, 1050, 1075, 1100, 1125, 1150, 1175, 1200]
    betas = (3000.0, 12000.0, 50000.0, 200000.0)
    for i, N in enumerate(Ns):
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slices_left = len(Ns) - i
        slice_deadline = now + remaining / slices_left
        h = _interp_to(best, N)
        if h.sum() <= 0:
            h = np.ones(N)
        h = h / h.max()
        hb, cb = _polish_lbfgs(h, slice_deadline, betas=betas)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
        if time.process_time() < slice_deadline:
            hb2, cb2 = _active_set_polish(hb, slice_deadline, tol_rel=1e-4)
            if cb2 < bestC:
                bestC = cb2
                best = hb2.copy()

    # Extra polish on the best found so far.
    if time.process_time() < deadline:
        hb, cb = _polish_lbfgs(best, deadline, betas=betas)
        if cb < bestC:
            bestC = cb
            best = hb
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-4)
        if cb < bestC:
            bestC = cb
            best = hb

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _refine_sm(h, betas, deadline):
    state = {'best': h.copy(), 'bestC': _C(h)}
    for beta in betas:
        if time.process_time() >= deadline:
            break

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-13})
            xf = res.x
            c = _C(xf)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xf.copy()
        except StopIteration:
            pass
    return state['best'], state['bestC']


def _pnorm_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    cpos = np.maximum(conv, 0.0)
    cp = cpos ** (p - 1)
    sp = float(np.sum(cpos ** p))
    if sp <= 0:
        return 1e18, np.zeros(N)
    spow = sp ** (1.0 / p)
    J = spow / (S * S)
    w = sp ** (1.0 / p - 1.0) * cp
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: N - 1 + N]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _refine_pnorm(h, ps, deadline):
    state = {'best': h.copy(), 'bestC': _C(h)}
    for p in ps:
        if time.process_time() >= deadline:
            break

        def fun(x, _p=p):
            return _pnorm_obj(x, _p)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-13})
            xf = res.x
            c = _C(xf)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xf.copy()
        except StopIteration:
            pass
    return state['best'], state['bestC']


def _peak_grad(h):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N)
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    C = 2.0 * N * conv[k] / (S * S)
    g = np.zeros(N)
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
    g[lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
    return g


def _adam_polish(h, deadline, max_iter=4000, lr=0.005):
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = len(h)
    if N == 0 or h.sum() <= 0:
        return h
    x = np.log(np.maximum(h, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    best = h.copy()
    bestC = _C(h)
    for t in range(1, max_iter + 1):
        if time.process_time() >= deadline:
            break
        hh = np.exp(x)
        g = _peak_grad(hh)
        gl = g * hh
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        hh2 = np.exp(x)
        c2 = _C(hh2)
        if c2 < bestC:
            bestC = c2
            best = hh2.copy()
    return best


def _coord_polish(hh, C, deadline):
    rng = np.random.default_rng(999)
    step = 0.02
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(len(hh))
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = hh[i]
            for fac in (1.0 + step, 1.0 - step):
                hh[i] = max(0.0, old * fac)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
            for d in (step * mean, -step * mean):
                hh[i] = max(0.0, old + d)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-7:
                break
    return hh, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
        else:
            seed = None
    else:
        seed = None

    if seed is None:
        x = np.linspace(-1, 1, 50)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Phase 0: p-norm continuation on the seed's N.
    if time.process_time() < deadline:
        h = best.copy()
        if h.sum() > 0:
            h = h / max(h.max(), 1e-12)
            ps = [10.0, 30.0, 100.0, 300.0]
            hb, hc = _refine_pnorm(h, ps, deadline)
            if hc < bestC:
                bestC = hc
                best = hb.copy()

    # Phase 1: softmax continuation at seed's N and neighbours.
    base_N = len(seed)
    N_list = []
    for f in (1.0, 2.0, 0.5):
        n = int(round(base_N * f))
        n = max(50, min(30000, n))
        if n not in N_list:
            N_list.append(n)
    betas = [1000.0, 4000.0, 16000.0, 64000.0, 256000.0]
    for N in N_list:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, N)
        if h.sum() <= 0:
            continue
        h = h / max(h.max(), 1e-12)
        hb, hc = _refine_sm(h, betas, deadline)
        if hc < bestC:
            bestC = hc
            best = hb.copy()

    # Phase 2: Adam in log-space.
    if time.process_time() < deadline:
        polished = _adam_polish(best, deadline, max_iter=4000, lr=0.004)
        cp = _C(polished)
        if cp < bestC:
            bestC = cp
            best = polished.copy()

    # Phase 3: coordinate polish on exact C.
    if time.process_time() < deadline:
        hh, C = _coord_polish(best.copy(), bestC, deadline)
        if C < bestC:
            bestC = C
            best = hh.copy()

    # NEW Phase 4: try smaller N (compression) — often reduces C further.
    if time.process_time() < deadline:
        base = len(best)
        for frac in (0.75, 0.5, 0.9, 0.6, 0.85):
            if time.process_time() >= deadline:
                break
            N = max(50, int(round(base * frac)))
            h = _interp_to(best, N)
            if h.sum() <= 0:
                continue
            h = h / max(h.max(), 1e-12)
            hb, hc = _refine_sm(h, betas, deadline)
            if hc < bestC:
                bestC = hc
                best = hb.copy()
            if time.process_time() < deadline:
                polished = _adam_polish(best, deadline, max_iter=1500, lr=0.003)
                cp = _C(polished)
                if cp < bestC:
                    bestC = cp
                    best = polished.copy()

