    return state['best'].copy(), state['bestC']


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


