    for i, N in enumerate(Ns):
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slices_left = len(Ns) - i + 1
        slice_deadline = now + remaining / slices_left
        h = _interp_to(best, N)
        if h.sum() <= 0:
            continue
        h = h / h.max()
        hb, cb = _polish_lbfgs(h, slice_deadline, betas=betas_near)
        if cb < bestC:
            bestC, best = cb, hb.copy()
            if time.process_time() < slice_deadline:
                hb2, cb2 = _active_set_polish(hb, slice_deadline, tol_rel=1e-4)
                if cb2 < bestC:
                    bestC, best = cb2, hb2.copy()

    # 3) Final active-set / softmax polish on the best so far.
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-5)
        if cb < bestC:
