                               betas=(50000.0, 200000.0, 800000.0))
        if cb < bestC:
            bestC, best = cb, hb.copy()

    # 4) Trim tiny entries to tighten support (may help slightly; safe since C is scale-invariant).
    trimmed = _trim(best, thresh=0.0)
    if trimmed.size > 0 and _C_fast(trimmed) <= bestC + 1e-12:
        best = trimmed

