    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
