def _refine_at_N(h_seed, N2, deadline):
    h2 = _interp_to(h_seed, N2)
    best = h2.copy()
    bestC = _C(best)

    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-3, maxiter=400)
        if cb < bestC:
            best, bestC = hb, cb
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-4, maxiter=400)
        if cb < bestC:
            best, bestC = hb, cb
    if time.process_time() < deadline:
        hb, cb = _polish_lbfgs(best, deadline, betas=(50000.0,), maxiter=400)
        if cb < bestC:
            best, bestC = hb, cb
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-4, maxiter=400)
        if cb < bestC:
            best, bestC = hb, cb
    return best, bestC


def _continuation_descend(h, deadline, N_min=200, factor=0.75):
    """Gradually shrink N, polishing at each stage. Returns best (h, C)."""
    best = h.copy()
    bestC = _C(best)
    while time.process_time() < deadline:
        N = len(best)
        if N <= N_min:
            break
        N2 = max(N_min, int(N * factor))
        if N2 >= N:
            break
        hb, cb = _refine_at_N(best, N2, deadline)
        if cb < bestC:
            best, bestC = hb, cb
        else:
            # still take the smaller representation if equal-ish, else stop
            if cb <= bestC * (1.0 + 1e-6):
                best, bestC = hb, cb
            else:
                break
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("seed N=%d C=%.9f" % (len(best), bestC))

    # Phase 1: refine at the seed's own N to squeeze more out of it.
    if time.process_time() < deadline:
        now = time.process_time()
        slice_deadline = now + (deadline - now) * 0.5
        hb, cb = _refine_at_N(best, len(best), slice_deadline)
        if cb < bestC:
            best, bestC = hb, cb
        print("refine N=%d -> C=%.9f (cpu %.1f)" % (len(best), bestC, time.process_time() - t0))

    # Phase 2: continuation descent to smaller N (finer steps often lower C).
    if time.process_time() < deadline:
        hb, cb = _continuation_descend(best, deadline, N_min=180, factor=0.8)
        if cb < bestC:
            best, bestC = hb, cb
        print("descend N=%d -> C=%.9f (cpu %.1f)" % (len(best), bestC, time.process_time() - t0))

    # Phase 3: if time remains, try a couple more N targets.
    if time.process_time() < deadline:
        for N2 in (len(best), max(120, int(len(best) * 0.85))):
            now = time.process_time()
            if now >= deadline:
                break
            hb, cb = _refine_at_N(best, N2, deadline)
            if cb < bestC:
                best, bestC = hb, cb
            print("N=%d -> C=%.9f (cpu %.1f)" % (N2, cb, time.process_time() - t0))

    print("final N=%d C=%.9f" % (len(best), bestC))
    return np.asarray(best, dtype=float)

