    for j in range(1, n_modes + 1):
        a = rng.standard_normal()
        phi = rng.uniform(0.0, 2.0 * np.pi)
        logmod += a * np.cos(np.pi * j * x + phi)
    h = seed * np.exp(amp * logmod)
