                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       callback=cb,
                       options={'maxiter': 3000, 'maxfun': 30000,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _prune_and_reopt(h, threshold, deadline, tol_rel=1e-4):
    """Zero out entries below threshold*max, freeze them, reopt nonzero entries."""
    N = len(h)
    mx = h.max()
    if mx <= 0:
        return h.copy(), _C(h)
    mask = h >= threshold * mx
    if mask.sum() == 0 or mask.sum() == N:
        return h.copy(), _C(h)
    idx = np.where(mask)[0]
    h_full = np.zeros(N)
    h_full[idx] = h[idx]

    def fun(x):
        hf = np.zeros(N)
        hf[idx] = x
        Cval, g = _active_set_obj(hf, tol_rel)
        return Cval, g[idx]

    state = {'best': h_full.copy(), 'bestC': _C(h_full)}

    def cb(xk):
        hf = np.zeros(N)
        hf[idx] = xk
        c = _C(hf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = hf.copy()

    try:
        res = minimize(fun, h_full[idx].copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(idx),
                       callback=cb,
                       options={'maxiter': 3000, 'maxfun': 30000,
                                'ftol': 1e-16, 'gtol': 1e-14})
        hf = np.zeros(N)
        hf[idx] = res.x
        c = _C(hf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = hf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # === Basin-hop experiment ===
    # Loop while time remains (cap ~12 iterations): copy best, zero a random
    # contiguous block (biased to the first/last 20% of indices), reoptimize.
    rng = np.random.default_rng(20240607)
    N = len(best)
    max_iters = 12
    for it in range(max_iters):
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        iters_left = max_iters - it
        slice_deadline = now + remaining / iters_left

        h = best.copy()
        L = int(rng.integers(4, 41))
        L = min(L, N)
        # Bias position to first/last 20% of indices.
        if rng.random() < 0.5:
            lo = 0
            hi = max(1, int(0.2 * N) - L)
        else:
            lo = min(N - L, int(0.8 * N))
            hi = N - L
        if hi < lo:
            lo, hi = 0, N - L
        pos = int(rng.integers(lo, hi + 1)) if hi >= lo else 0
        h[pos:pos + L] = 0.0

        hb, cb = _active_set_polish(h, slice_deadline, tol_rel=1e-4)
        if time.process_time() < slice_deadline:
            hb2, cb2 = _polish_lbfgs(hb, slice_deadline, betas=(12000.0, 50000.0))
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _conv_max_grad(h):
    """Return (M, grad of M w.r.t. h, averaged over active set)."""
    N = len(h)
    conv = np.convolve(h, h)
    M = float(conv.max())
    return conv, M


def _lse_obj(h, beta, K_frac=None):
    """Log-sum-exp smoothing of max(conv), with C = 2N*M/S^2."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    Msoft = logZ / beta
    J = 2.0 * N * Msoft / (S * S)
    p = e / Z
    # dMsoft/dh_i = 2 * sum_k p_k * h_{k-i}
    corr = np.convolve(p, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1]
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * Msoft) / (S * S * S)
    return J, grad


def _lp_obj(h, p):
    """L^p smoothing: J = (sum(conv**p))**(1/p) / S^2, scaled by 2N."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    Mp = m * Zp
    J = 2.0 * N * Mp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0))
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1]
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * Mp) / (S * S * S)
    return J, grad


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _run_lbfgs(fun, h0, deadline, maxiter=2500):
    state = {'best': h0.copy(), 'bestC': _C(h0)}

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h0),
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 10 * maxiter,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _lse_polish(h, deadline, betas=(200.0, 1000.0, 5000.0, 25000.0, 125000.0)):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        hb, cb = _run_lbfgs(lambda x, _b=beta: _lse_obj(x, _b), best, deadline)
        if cb < bestC:
            bestC = cb
            best = hb
    return best, bestC


def _lp_polish(h, deadline, ps=(8.0, 32.0, 128.0, 512.0, 2048.0)):
    best = h.copy()
    bestC = _C(h)
    for p in ps:
        if time.process_time() >= deadline:
            break
        hb, cb = _run_lbfgs(lambda x, _p=p: _lp_obj(x, _p), best, deadline)
        if cb < bestC:
            bestC = cb
            best = hb
    return best, bestC


def _active_set_polish(h, deadline, tol_rel=1e-6):
    best = h.copy()
    bestC = _C(h)
    hb, cb = _run_lbfgs(lambda x: _active_set_obj(x, tol_rel), best, deadline)
    if cb < bestC:
        best, bestC = hb, cb
    return best, bestC


def _prune_and_reopt(h, threshold, deadline, tol_rel=1e-5):
    N = len(h)
    mx = h.max()
    if mx <= 0:
        return h.copy(), _C(h)
    mask = h >= threshold * mx
    nkeep = int(mask.sum())
    if nkeep == 0 or nkeep == N:
        return h.copy(), _C(h)
    idx = np.where(mask)[0]
    h_full = np.zeros(N)
    h_full[idx] = h[idx]

    def fun(x):
        hf = np.zeros(N)
        hf[idx] = x
        Cval, g = _active_set_obj(hf, tol_rel)
        return Cval, g[idx]

    hb, cb = _run_lbfgs(fun, h_full[idx].copy(), deadline)
    hf = np.zeros(N)
    hf[idx] = hb
    c = _C(hf)
    if c < _C(h_full):
        return hf, c
    return h_full, _C(h_full)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Reserve ~45% for final N sweep; use ~55% for polishing.
    sweep_start = t0 + budget_seconds * 0.88 * 0.55

    # === Round 1: L^p smoothing (good global convergence at low N) ===
    hb, cb = _lp_polish(best, sweep_start, ps=(8.0, 32.0, 128.0, 512.0, 2048.0, 8192.0))
    if cb < bestC:
        bestC, best = cb, hb
    print("after Lp: C=%.9f" % bestC)

    # === Round 2: LSE smoothing (sharper max approximation) ===
    if time.process_time() < sweep_start:
        hb, cb = _lse_polish(best, sweep_start, betas=(500.0, 2500.0, 12500.0, 62500.0, 250000.0))
        if cb < bestC:
            bestC, best = cb, hb
    print("after LSE: C=%.9f" % bestC)

    # === Round 3: Active set polish (true max gradient) ===
    if time.process_time() < sweep_start:
        hb, cb = _active_set_polish(best, sweep_start, tol_rel=1e-5)
        if cb < bestC:
            bestC, best = cb, hb
    print("after active: C=%.9f" % bestC)

    # === Round 4: Prune tiny entries and reoptimize ===
    if time.process_time() < sweep_start:
        hb, cb = _prune_and_reopt(best, 1e-3, sweep_start)
        if cb < bestC:
            bestC, best = cb, hb
        if time.process_time() < sweep_start:
            hb, cb = _prune_and_reopt(best, 1e-2, sweep_start)
            if cb < bestC:
                bestC, best = cb, hb
    print("after prune: C=%.9f" % bestC)

    # === Fine N sweep around current best N ===
    Nc = len(best)
    cand = set()
    for d in range(-40, 41, 4):
        n = Nc + d
        if 1 <= n <= 30000:
            cand.add(n)
    N_list = sorted(cand)
    if Nc not in N_list:
        N_list.append(Nc)
    n_left = len(N_list)
    for N2 in N_list:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        n_left_eff = max(1, n_left)
        n_left -= 1
        slice_deadline = now + remaining / n_left_eff

        if N2 == Nc:
            h2 = best.copy()
        else:
            h2 = _interp_to(best, N2)
        hb, cb = _active_set_polish(h2, slice_deadline, tol_rel=1e-5)
        if time.process_time() < slice_deadline:
            hb2, cb2 = _lse_polish(hb, slice_deadline, betas=(25000.0, 125000.0))
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < bestC:
            bestC, best = cb, hb

    # Final active-set polish at current N.
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-5)
        if cb < bestC:
            bestC, best = cb, hb

    print("final C=%.9f N=%d" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    """L^p smoothing: J = (sum(conv**p))**(1/p) / S^2."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _topk_obj(h, K):
    """Average of top-K convolution values: J = 2N*mean(conv[topK])/S^2."""
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    L = len(conv)
    K = max(1, min(int(K), L))
    if K < L:
        idx = np.argpartition(conv, L - K)[L - K:]
    else:
        idx = np.arange(L)
    Mavg = float(conv[idx].mean())
    # gradient of mean of selected conv values wrt h
    gM = np.zeros(N)
    for k in idx:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        j = np.arange(lo, hi + 1)
        gM[j] += 2.0 * h[k - j]
    gM /= K
    J = 2.0 * N * Mavg / (S * S)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * Mavg) / (S * S * S)
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0)):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
