def _zero_runs(h, thresh):
    """Return list of (a,b) inclusive index ranges where h < thresh."""
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=2):
    """Try shifting/restoring zero-run boundaries; accept only true C decreases."""
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False
        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            candidates = []
            # set a-1 = 0
            if a - 1 >= 0 and best[a - 1] >= thresh:
                candidates.append(('zero_left', a - 1))
            # set b+1 = 0
            if b + 1 < N and best[b + 1] >= thresh:
                candidates.append(('zero_right', b + 1))
            # restore a from a-1
            if a - 1 >= 0 and a <= b:
                candidates.append(('restore_a_from_left', a))
            # restore b from b+1
            if b + 1 < N and a <= b:
                candidates.append(('restore_b_from_right', b))
            # shift left: zero b, restore a-1
            if a - 1 >= 0 and b + 1 < N:
                candidates.append(('shift_left', None))
            # shift right: zero a, restore b+1
            if a - 1 >= 0 and b + 1 < N:
                candidates.append(('shift_right', None))

            for kind, idx in candidates:
                if time.process_time() >= deadline:
                    break
                cand = best.copy()
                if kind == 'zero_left':
                    cand[idx] = 0.0
                elif kind == 'zero_right':
                    cand[idx] = 0.0
                elif kind == 'restore_a_from_left':
                    cand[idx] = max(best[a - 1], tiny)
                elif kind == 'restore_b_from_right':
                    cand[idx] = max(best[b + 1], tiny)
                elif kind == 'shift_left':
                    cand[a - 1] = max(best[a - 1], tiny)
                    cand[b] = 0.0
                elif kind == 'shift_right':
                    cand[a] = 0.0
                    cand[b + 1] = max(best[b + 1], tiny)
                c0 = _C(cand)
                if c0 >= bestC:
                    continue
                # local polish on candidate
                hb, cb = _active_set_polish(cand, deadline, tol_rel=1e-4, maxiter=300)
                if cb < bestC - 1e-12:
                    best = hb
                    bestC = cb
                    accepted_any = True
                    break
            if accepted_any and time.process_time() >= deadline:
                break
        if not accepted_any:
            break
    return best, bestC


