        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6, maxiter=3000):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _active_set_schedule(h, deadline, tols=(1e-4, 1e-6), maxiter=1500):
    best = h.copy()
    bestC = _C(h)
    for tol in tols:
        if time.process_time() >= deadline:
            break
        hb, cb = _active_set_polish(best, deadline, tol_rel=tol, maxiter=maxiter)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    return best, bestC


def _prune_and_reopt(h, threshold, deadline, tol_rel=1e-4):
    N = len(h)
    mx = h.max()
    if mx <= 0:
        return h.copy(), _C(h)
    mask = h >= threshold * mx
    if mask.sum() == 0 or mask.sum() == N:
