def _zero_runs(h, thresh):
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=2):
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False
        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            candidates = []
            if a - 1 >= 0 and best[a - 1] >= thresh:
                candidates.append(('zero_left', a - 1))
            if b + 1 < N and best[b + 1] >= thresh:
                candidates.append(('zero_right', b + 1))
            if a - 1 >= 0 and a <= b:
                candidates.append(('restore_a_from_left', a))
            if b + 1 < N and a <= b:
                candidates.append(('restore_b_from_right', b))
            if a - 1 >= 0 and b + 1 < N:
                candidates.append(('shift_left', None))
            if a - 1 >= 0 and b + 1 < N:
                candidates.append(('shift_right', None))

            for kind, idx in candidates:
                if time.process_time() >= deadline:
                    break
                cand = best.copy()
                if kind == 'zero_left':
                    cand[idx] = 0.0
                elif kind == 'zero_right':
                    cand[idx] = 0.0
                elif kind == 'restore_a_from_left':
                    cand[idx] = max(best[a - 1], tiny)
                elif kind == 'restore_b_from_right':
                    cand[idx] = max(best[b + 1], tiny)
                elif kind == 'shift_left':
                    cand[a - 1] = max(best[a - 1], tiny)
                    cand[b] = 0.0
                elif kind == 'shift_right':
                    cand[a] = 0.0
                    cand[b + 1] = max(best[b + 1], tiny)
                c0 = _C(cand)
                if c0 >= bestC:
                    continue
                hb, cb = _active_set_polish(cand, deadline, tol_rel=1e-4, maxiter=300)
                if cb < bestC - 1e-12:
                    best = hb
                    bestC = cb
                    accepted_any = True
                    break
            if accepted_any and time.process_time() >= deadline:
                break
        if not accepted_any:
            break
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # === NEW EXPERIMENT: finer step resolution via doubling ===
    # Reserve most of the budget for the doubling sweep.
    N0 = len(best)
    N_levels = [2 * N0, 4 * N0]
    # If N0 is already large, still try doubling once.
    if N0 > 15000:
        N_levels = [min(30000, 2 * N0)]

    # Give each level a time slice; allow extra doubling if improvement.
    level_idx = 0
    while level_idx < len(N_levels):
        N2 = N_levels[level_idx]
        if N2 > 30000:
            break
        now = time.process_time()
        if now >= deadline:
            break
        levels_left = len(N_levels) - level_idx
        slice_deadline = now + (deadline - now) / levels_left

        h2 = _interp_to(best, N2)
        hb, cb = _active_set_schedule(h2, slice_deadline, tols=(1e-4, 1e-6), maxiter=1500)
        improved = cb < bestC - 1e-12
        if improved:
            bestC = cb
            best = hb.copy()
        print("N=%d: C=%.9f%s" % (N2, cb, " *" if improved else ""))

        # If this level improved, try one more doubling within budget.
        if improved and level_idx == len(N_levels) - 1:
            N3 = 2 * N2
            if N3 <= 30000 and time.process_time() < deadline:
                N_levels.append(N3)
        level_idx += 1

    # Final polish at current best N with remaining time.
    if time.process_time() < deadline:
        hb, cb = _active_set_schedule(best, deadline, tols=(1e-6,), maxiter=2000)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
        print("final: C=%.9f" % bestC)

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0)):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _lp_polish(h, deadline, ps=(8.0, 32.0, 128.0, 512.0, 2048.0)):
