def _zero_runs(h, thresh):
    """Return list of (a,b) inclusive index ranges where h < thresh."""
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=2):
    """Extended boundary search: shift whole zero runs by d=1..5, expand/shrink
    each end by 1..3, and zero/restore isolated nonzero neighbors. For any
    candidate beating bestC, run active-set polish with tol_rel 1e-4 then 1e-6,
    accepting only exact-C improvements."""
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    def _polish_candidate(cand, cur_bestC):
        """Run active-set polish with tol schedule; return (h, C) if improved."""
        # First pass tol_rel=1e-4
        hb, cb = _active_set_polish(cand, deadline, tol_rel=1e-4, maxiter=400)
        if cb >= cur_bestC:
            return None, cur_bestC
        # Second pass tol_rel=1e-6 if time remains
        if time.process_time() < deadline:
            hb2, cb2 = _active_set_polish(hb, deadline, tol_rel=1e-6, maxiter=400)
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < cur_bestC - 1e-14:
            return hb, cb
        return None, cur_bestC

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False
        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            run_len = b - a + 1

            # Build candidate list of (kind, params)
            candidates = []

            # Shift whole run left/right by d=1..5
            for d in range(1, 6):
                # shift left: zero indices [b-d+1, b], restore [a-d, a-1]
                if a - d >= 0:
                    candidates.append(('shift_whole', -d))
                # shift right: zero [a, a+d-1], restore [b+1, b+d]
                if b + d < N:
                    candidates.append(('shift_whole', d))

            # Expand/shrink each end by 1..3
            for k in range(1, 4):
                # shrink left end: restore a..a+k-1
                if a + k - 1 <= b:
                    candidates.append(('shrink_left', k))
                # shrink right end: restore b-k+1..b
                if b - k + 1 >= a:
                    candidates.append(('shrink_right', k))
                # expand left end: zero a-k..a-1
                if a - k >= 0:
                    candidates.append(('expand_left', k))
                # expand right end: zero b+1..b+k
                if b + k < N:
                    candidates.append(('expand_right', k))

            # Zero/restore isolated nonzero neighbors
            if a - 1 >= 0 and best[a - 1] >= thresh:
                candidates.append(('zero_neighbor', a - 1))
            if b + 1 < N and best[b + 1] >= thresh:
                candidates.append(('zero_neighbor', b + 1))
            if a - 1 >= 0:
                candidates.append(('restore_a', a))
            if b + 1 < N:
                candidates.append(('restore_b', b))

            for kind, param in candidates:
                if time.process_time() >= deadline:
                    break
                cand = best.copy()
                ok = True
                if kind == 'shift_whole':
                    d = param
                    if d < 0:
                        d = -d
                        # shift left
                        for i in range(b - d + 1, b + 1):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(a - d, a):
                            if 0 <= i < N:
                                cand[i] = max(best[a], tiny)
                    else:
                        # shift right
                        for i in range(a, a + d):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(b + 1, b + d + 1):
                            if 0 <= i < N:
                                cand[i] = max(best[b], tiny)
                elif kind == 'shrink_left':
                    k = param
                    for i in range(a, a + k):
                        cand[i] = max(best[a - 1] if a - 1 >= 0 else best[a], tiny)
                elif kind == 'shrink_right':
                    k = param
                    for i in range(b - k + 1, b + 1):
                        cand[i] = max(best[b + 1] if b + 1 < N else best[b], tiny)
                elif kind == 'expand_left':
                    k = param
                    for i in range(a - k, a):
                        cand[i] = 0.0
                elif kind == 'expand_right':
                    k = param
                    for i in range(b + 1, b + k + 1):
                        cand[i] = 0.0
                elif kind == 'zero_neighbor':
                    cand[param] = 0.0
                elif kind == 'restore_a':
                    if a - 1 >= 0:
                        cand[a] = max(best[a - 1], tiny)
                    else:
                        ok = False
                elif kind == 'restore_b':
                    if b + 1 < N:
                        cand[b] = max(best[b + 1], tiny)
                    else:
                        ok = False
                if not ok:
                    continue
                c0 = _C(cand)
                if c0 >= bestC:
                    continue
                hb, cb = _polish_candidate(cand, bestC)
                if hb is not None and cb < bestC - 1e-14:
                    best = hb
                    bestC = cb
                    accepted_any = True
                    break
            if accepted_any and time.process_time() >= deadline:
                break
        if not accepted_any:
            break
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

