        if cb < bestC:
            bestC = cb
            best = hb.copy()
    return best, bestC


def _prune_and_reopt(h, threshold, deadline, tol_rel=1e-4):
    N = len(h)
    mx = h.max()
    if mx <= 0:
        return h.copy(), _C(h)
    mask = h >= threshold * mx
    if mask.sum() == 0 or mask.sum() == N:
        return h.copy(), _C(h)
    idx = np.where(mask)[0]
    h_full = np.zeros(N)
    h_full[idx] = h[idx]

    def fun(x):
        hf = np.zeros(N)
        hf[idx] = x
        Cval, g = _active_set_obj(hf, tol_rel)
        return Cval, g[idx]

    state = {'best': h_full.copy(), 'bestC': _C(h_full)}

    def cb(xk):
        hf = np.zeros(N)
        hf[idx] = xk
        c = _C(hf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = hf.copy()

    try:
        res = minimize(fun, h_full[idx].copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(idx),
                       callback=cb,
                       options={'maxiter': 3000, 'maxfun': 30000,
                                'ftol': 1e-16, 'gtol': 1e-14})
        hf = np.zeros(N)
        hf[idx] = res.x
        c = _C(hf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = hf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


