def _resample(h, N):
    """Mass-preserving resample: split each cell's mass uniformly across overlap."""
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    # cumulative mass at cell boundaries in [0,1]
    edges_src = np.linspace(0.0, 1.0, M + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges_dst = np.linspace(0.0, 1.0, N + 1)
    mass_at_edges = np.interp(edges_dst, edges_src, cum)
    out = np.diff(mass_at_edges)
    # convert mass back to height (cell width differs)
    out = out * (N / M)
    out = np.maximum(out, 0.0)
    return out


