            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 10 * maxiter,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_polish(h, deadline, tol_rel=1e-4, maxiter=1500):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 10 * maxiter,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    edges_src = np.linspace(0.0, 1.0, M + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges_dst = np.linspace(0.0, 1.0, N + 1)
    out = np.diff(np.interp(edges_dst, edges_src, cum))
    return np.maximum(out * (N / M), 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 200
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Phase 1: strong polish of the start using tight active-set then softmax.
    hb, cb = _active_set_polish(best, deadline, tol_rel=1e-5, maxiter=1500)
    if cb < bestC:
        best, bestC = hb, cb
    if time.process_time() < deadline:
        hb, cb = _polish_lbfgs(best, deadline,
                               betas=(20000.0, 100000.0, 400000.0), maxiter=1500)
        if cb < bestC:
            best, bestC = hb, cb
    print("after initial polish: C=%.9f N=%d" % (bestC, len(best)))

    # Phase 2: local N sweep (fine near current N, mass-preserving).
    Nc = len(best)
    span = max(10, min(40, Nc // 12))
    N_list = sorted(range(max(1, Nc - span), min(30000, Nc + span) + 1),
                    key=lambda n: (n != Nc, abs(n - Nc)))
    for N2 in N_list:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slice_deadline = now + remaining * 0.5 / max(1, len(N_list))
        h2 = _resample(best, N2)
        hb, cb = _active_set_polish(h2, slice_deadline, tol_rel=1e-4, maxiter=300)
        if time.process_time() < slice_deadline:
            hb2, cb2 = _polish_lbfgs(hb, slice_deadline,
                                     betas=(20000.0, 100000.0), maxiter=300)
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < bestC:
            bestC, best = cb, hb.copy()
    print("after resample sweep: C=%.9f N=%d" % (bestC, len(best)))

    # Phase 3: final strong polish.
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-5, maxiter=2000)
        if cb < bestC:
            bestC, best = cb, hb
    if time.process_time() < deadline:
        hb, cb = _polish_lbfgs(best, deadline,
                               betas=(50000.0, 200000.0, 800000.0), maxiter=2000)
        if cb < bestC:
            bestC, best = cb, hb
    print("final: C=%.9f N=%d" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0)):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _lp_polish(h, deadline, ps=(8.0, 32.0, 128.0, 512.0, 2048.0)):
    best = h.copy()
    bestC = _C(h)
    for p in ps:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _p=p):
            return _lp_obj(x, _p)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 3000, 'maxfun': 30000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6, maxiter=3000):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _prune_and_reopt(h, threshold, deadline, tol_rel=1e-4):
    N = len(h)
    mx = h.max()
    if mx <= 0:
        return h.copy(), _C(h)
    mask = h >= threshold * mx
    if mask.sum() == 0 or mask.sum() == N:
        return h.copy(), _C(h)
    idx = np.where(mask)[0]
    h_full = np.zeros(N)
    h_full[idx] = h[idx]

    def fun(x):
        hf = np.zeros(N)
        hf[idx] = x
        Cval, g = _active_set_obj(hf, tol_rel)
        return Cval, g[idx]

    state = {'best': h_full.copy(), 'bestC': _C(h_full)}

    def cb(xk):
        hf = np.zeros(N)
        hf[idx] = xk
        c = _C(hf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = hf.copy()

    try:
        res = minimize(fun, h_full[idx].copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(idx),
                       callback=cb,
                       options={'maxiter': 3000, 'maxfun': 30000,
                                'ftol': 1e-16, 'gtol': 1e-14})
        hf = np.zeros(N)
        hf[idx] = res.x
        c = _C(hf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = hf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _zero_runs(h, thresh):
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=2):
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    def _polish_candidate(cand, cur_bestC):
        hb, cb = _active_set_polish(cand, deadline, tol_rel=1e-4, maxiter=400)
        if cb >= cur_bestC:
            return None, cur_bestC
        if time.process_time() < deadline:
            hb2, cb2 = _active_set_polish(hb, deadline, tol_rel=1e-6, maxiter=400)
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < cur_bestC - 1e-14:
            return hb, cb
        return None, cur_bestC

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False
        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            candidates = []
            for d in range(1, 6):
                if a - d >= 0:
                    candidates.append(('shift_whole', -d))
                if b + d < N:
                    candidates.append(('shift_whole', d))
            for k in range(1, 4):
                if a + k - 1 <= b:
                    candidates.append(('shrink_left', k))
                if b - k + 1 >= a:
                    candidates.append(('shrink_right', k))
                if a - k >= 0:
                    candidates.append(('expand_left', k))
                if b + k < N:
                    candidates.append(('expand_right', k))
            if a - 1 >= 0 and best[a - 1] >= thresh:
                candidates.append(('zero_neighbor', a - 1))
            if b + 1 < N and best[b + 1] >= thresh:
                candidates.append(('zero_neighbor', b + 1))
            if a - 1 >= 0:
                candidates.append(('restore_a', a))
            if b + 1 < N:
                candidates.append(('restore_b', b))

            for kind, param in candidates:
                if time.process_time() >= deadline:
                    break
                cand = best.copy()
                ok = True
                if kind == 'shift_whole':
                    d = param
                    if d < 0:
                        d = -d
                        for i in range(b - d + 1, b + 1):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(a - d, a):
                            if 0 <= i < N:
                                cand[i] = max(best[a], tiny)
                    else:
                        for i in range(a, a + d):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(b + 1, b + d + 1):
                            if 0 <= i < N:
                                cand[i] = max(best[b], tiny)
                elif kind == 'shrink_left':
                    k = param
                    for i in range(a, a + k):
                        cand[i] = max(best[a - 1] if a - 1 >= 0 else best[a], tiny)
                elif kind == 'shrink_right':
                    k = param
                    for i in range(b - k + 1, b + 1):
                        cand[i] = max(best[b + 1] if b + 1 < N else best[b], tiny)
                elif kind == 'expand_left':
                    k = param
                    for i in range(a - k, a):
                        cand[i] = 0.0
                elif kind == 'expand_right':
                    k = param
                    for i in range(b + 1, b + k + 1):
                        cand[i] = 0.0
                elif kind == 'zero_neighbor':
                    cand[param] = 0.0
                elif kind == 'restore_a':
                    if a - 1 >= 0:
                        cand[a] = max(best[a - 1], tiny)
                    else:
                        ok = False
                elif kind == 'restore_b':
                    if b + 1 < N:
                        cand[b] = max(best[b + 1], tiny)
                    else:
                        ok = False
                if not ok:
                    continue
                c0 = _C(cand)
                if c0 >= bestC:
                    continue
                hb, cb = _polish_candidate(cand, bestC)
                if hb is not None and cb < bestC - 1e-14:
                    best = hb
                    bestC = cb
                    accepted_any = True
                    break
            if accepted_any and time.process_time() >= deadline:
                break
        if not accepted_any:
            break
    return best, bestC


def _subgradient_descent(h, deadline, iters=2000):
    """Projected subgradient / mirror descent on the true max objective,
    with sum(h)=1 fixed. Tracks best exact C."""
    N = len(h)
    x = np.asarray(h, dtype=float).copy()
    s = x.sum()
    if s <= 0:
        return h.copy(), _C(h)
    x /= s
    best = x.copy()
    bestC = _C(x)

    # eta schedule: 1e-3 down to 1e-7 (log scale)
    etas = np.logspace(np.log10(1e-3), np.log10(1e-7), iters)

    for it in range(iters):
        if (it & 63) == 0 and time.process_time() >= deadline:
            break
        conv = np.convolve(x, x)
        M = float(conv.max())
        tol = 1e-6 * M
        K = np.where(conv >= M - tol)[0]
        if len(K) == 0:
            break
        # g_i = 2N*mean_{k in K} h_{k-i} - 4N*M  (with S=1)
        gM = np.zeros(N)
        invK = 1.0 / len(K)
        for k in K:
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            idx = np.arange(lo, hi + 1)
            gM[idx] += x[k - idx]
        gM *= invK
        grad = 2.0 * N * gM - 4.0 * N * M

        eta = etas[it]
        x = x - eta * grad
        np.maximum(x, 0.0, out=x)
        s = x.sum()
        if s <= 0:
            x = best.copy()
            continue
        x /= s

        if (it & 15) == 0:
            c = _C(x)
            if c < bestC:
                bestC = c
                best = x.copy()

    c = _C(x)
    if c < bestC:
        bestC = c
        best = x.copy()
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    sweep_start = t0 + budget_seconds * 0.88 * 0.60
    main_deadline = sweep_start

    # === NEW: projected subgradient on true max objective ===
    # Use the first ~35% of main phase for subgradient descent.
    sg_deadline = min(main_deadline, time.process_time() + 0.35 * (main_deadline - time.process_time()))
    if time.process_time() < sg_deadline:
        hsg, csg = _subgradient_descent(best, sg_deadline, iters=2000)
        if csg < bestC:
            bestC = csg
            best = hsg.copy()
        print("after subgradient: C=%.9f" % bestC)

    # Active-set polish on subgradient result.
    if time.process_time() < main_deadline:
        hb, cb = _active_set_polish(best, main_deadline, tol_rel=1e-6)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after active-set: C=%.9f" % bestC)

    # L^p smoothing (kept from base for robustness).
    if time.process_time() < main_deadline:
        hlp, clp = _lp_polish(best, main_deadline, ps=(8.0, 32.0, 128.0, 512.0, 2048.0))
        if clp < bestC:
            bestC = clp
            best = hlp.copy()
    print("after L^p: C=%.9f" % bestC)

    if time.process_time() < main_deadline:
        hb, cb = _active_set_polish(best, main_deadline, tol_rel=1e-4)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    if time.process_time() < main_deadline:
        hb, cb = _polish_lbfgs(best, main_deadline, betas=(12000.0, 50000.0))
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after polish: C=%.9f" % bestC)

    shift_deadline = min(main_deadline, time.process_time() + 0.8 * (main_deadline - time.process_time()))
    if time.process_time() < shift_deadline:
        hb, cb = _boundary_shift_search(best, shift_deadline, max_passes=2)
        if cb < bestC - 1e-12:
            bestC = cb
            best = hb.copy()
            print("after boundary shift: C=%.9f" % bestC)
        else:
            print("after boundary shift: no improvement (C=%.9f)" % bestC)

    # Fine N sweep around current size.
    Nc = len(best)
    lo = max(1, Nc - 30)
    hi = min(30000, Nc + 30)
    N_list = list(range(lo, hi + 1, 5))
    if Nc not in N_list:
        N_list.append(Nc)
    n_left = len(N_list)
    for N2 in N_list:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slices_left = n_left
        n_left -= 1
        slice_deadline = now + remaining / slices_left

        h2 = _interp_to(best, N2)
        hb, cb = _active_set_polish(h2, slice_deadline, tol_rel=1e-4)
        if time.process_time() < slice_deadline:
            hb2, cb2 = _polish_lbfgs(hb, slice_deadline, betas=(12000.0, 50000.0))
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _resample(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    edges_src = np.linspace(0.0, 1.0, M + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    edges_dst = np.linspace(0.0, 1.0, N + 1)
    mass_at_edges = np.interp(edges_dst, edges_src, cum)
    out = np.diff(mass_at_edges) * (N / M)
    return np.maximum(out, 0.0)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _polish_lbfgs(h, deadline, betas=(12000.0, 50000.0), maxiter=1500):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 10 * maxiter,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


