def _zero_runs(h, thresh):
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=2):
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    def _polish_candidate(cand, cur_bestC):
        hb, cb = _active_set_polish(cand, deadline, tol_rel=1e-4, maxiter=400)
        if cb >= cur_bestC:
            return None, cur_bestC
        if time.process_time() < deadline:
            hb2, cb2 = _active_set_polish(hb, deadline, tol_rel=1e-6, maxiter=400)
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < cur_bestC - 1e-14:
            return hb, cb
        return None, cur_bestC

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False
        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            candidates = []
            for d in range(1, 6):
                if a - d >= 0:
                    candidates.append(('shift_whole', -d))
                if b + d < N:
                    candidates.append(('shift_whole', d))
            for k in range(1, 4):
                if a + k - 1 <= b:
                    candidates.append(('shrink_left', k))
                if b - k + 1 >= a:
                    candidates.append(('shrink_right', k))
                if a - k >= 0:
                    candidates.append(('expand_left', k))
                if b + k < N:
                    candidates.append(('expand_right', k))
            if a - 1 >= 0 and best[a - 1] >= thresh:
                candidates.append(('zero_neighbor', a - 1))
            if b + 1 < N and best[b + 1] >= thresh:
                candidates.append(('zero_neighbor', b + 1))
            if a - 1 >= 0:
                candidates.append(('restore_a', a))
            if b + 1 < N:
                candidates.append(('restore_b', b))

            for kind, param in candidates:
                if time.process_time() >= deadline:
                    break
                cand = best.copy()
                ok = True
                if kind == 'shift_whole':
                    d = param
                    if d < 0:
                        d = -d
                        for i in range(b - d + 1, b + 1):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(a - d, a):
                            if 0 <= i < N:
                                cand[i] = max(best[a], tiny)
                    else:
                        for i in range(a, a + d):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(b + 1, b + d + 1):
                            if 0 <= i < N:
                                cand[i] = max(best[b], tiny)
                elif kind == 'shrink_left':
                    k = param
                    for i in range(a, a + k):
                        cand[i] = max(best[a - 1] if a - 1 >= 0 else best[a], tiny)
                elif kind == 'shrink_right':
                    k = param
                    for i in range(b - k + 1, b + 1):
                        cand[i] = max(best[b + 1] if b + 1 < N else best[b], tiny)
                elif kind == 'expand_left':
                    k = param
                    for i in range(a - k, a):
                        cand[i] = 0.0
                elif kind == 'expand_right':
                    k = param
                    for i in range(b + 1, b + k + 1):
                        cand[i] = 0.0
                elif kind == 'zero_neighbor':
                    cand[param] = 0.0
                elif kind == 'restore_a':
                    if a - 1 >= 0:
                        cand[a] = max(best[a - 1], tiny)
                    else:
                        ok = False
                elif kind == 'restore_b':
                    if b + 1 < N:
                        cand[b] = max(best[b + 1], tiny)
                    else:
                        ok = False
                if not ok:
                    continue
                c0 = _C(cand)
                if c0 >= bestC:
                    continue
                hb, cb = _polish_candidate(cand, bestC)
                if hb is not None and cb < bestC - 1e-14:
                    best = hb
                    bestC = cb
                    accepted_any = True
                    break
            if accepted_any and time.process_time() >= deadline:
                break
        if not accepted_any:
            break
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Split: ~55% for main polish + boundary; ~45% for N sweep.
    sweep_start = t0 + budget_seconds * 0.88 * 0.55
    main_deadline = sweep_start

    hlp, clp = _lp_polish(best, main_deadline, ps=(32.0, 128.0, 512.0, 2048.0))
    if clp < bestC:
        bestC = clp
        best = hlp.copy()
    print("after L^p: C=%.9f" % bestC)

    if time.process_time() < main_deadline:
        hb, cb = _active_set_polish(best, main_deadline, tol_rel=1e-4)
        if cb < bestC:
            bestC, best = cb, hb.copy()
    if time.process_time() < main_deadline:
        hb, cb = _polish_lbfgs(best, main_deadline, betas=(12000.0, 50000.0))
        if cb < bestC:
            bestC, best = cb, hb.copy()
    print("after polish: C=%.9f" % bestC)

    shift_deadline = min(main_deadline,
                         time.process_time() + 0.85 * (main_deadline - time.process_time()))
    if time.process_time() < shift_deadline:
        hb, cb = _boundary_shift_search(best, shift_deadline, max_passes=2)
        if cb < bestC - 1e-12:
            bestC, best = cb, hb.copy()
            print("after boundary shift: C=%.9f" % bestC)
        else:
            print("after boundary shift: no improvement (C=%.9f)" % bestC)

    # N sweep using mass-preserving resample (better than interp for step funcs).
    Nc = len(best)
    span = max(15, min(50, Nc // 10))
    lo = max(1, Nc - span)
    hi = min(30000, Nc + span)
    N_list = list(range(lo, hi + 1))
    if Nc not in N_list:
        N_list.append(Nc)
    N_list.sort(key=lambda n: (n != Nc, abs(n - Nc)))

    n_left = len(N_list)
    for N2 in N_list:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slice_deadline = now + remaining * 0.6 / n_left
        n_left -= 1

        h2 = _resample(best, N2)
        hb, cb = _active_set_polish(h2, slice_deadline, tol_rel=1e-4, maxiter=300)
        if time.process_time() < slice_deadline:
            hb2, cb2 = _polish_lbfgs(hb, slice_deadline,
                                     betas=(12000.0, 50000.0), maxiter=300)
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < bestC:
            bestC, best = cb, hb.copy()

    # Final strong polish at best N with remaining time.
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-5, maxiter=2000)
        if cb < bestC:
            bestC, best = cb, hb.copy()
    if time.process_time() < deadline:
        hb, cb = _polish_lbfgs(best, deadline,
                               betas=(20000.0, 100000.0, 400000.0), maxiter=2000)
        if cb < bestC:
            bestC, best = cb, hb.copy()
    print("final: C=%.9f N=%d" % (bestC, len(best)))

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0)):
    best = h.copy()
