    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6, maxiter=3000):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _zero_runs(h, thresh):
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=2):
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    def _polish_candidate(cand, cur_bestC):
        hb, cb = _active_set_polish(cand, deadline, tol_rel=1e-4, maxiter=400)
        if cb >= cur_bestC:
            return None, cur_bestC
        if time.process_time() < deadline:
            hb2, cb2 = _active_set_polish(hb, deadline, tol_rel=1e-6, maxiter=400)
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < cur_bestC - 1e-14:
            return hb, cb
        return None, cur_bestC

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False
        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            candidates = []
            for d in range(1, 6):
                if a - d >= 0:
                    candidates.append(('shift_whole', -d))
                if b + d < N:
                    candidates.append(('shift_whole', d))
            for k in range(1, 4):
                if a + k - 1 <= b:
                    candidates.append(('shrink_left', k))
                if b - k + 1 >= a:
                    candidates.append(('shrink_right', k))
                if a - k >= 0:
                    candidates.append(('expand_left', k))
                if b + k < N:
                    candidates.append(('expand_right', k))
            if a - 1 >= 0 and best[a - 1] >= thresh:
                candidates.append(('zero_neighbor', a - 1))
            if b + 1 < N and best[b + 1] >= thresh:
                candidates.append(('zero_neighbor', b + 1))
            if a - 1 >= 0:
                candidates.append(('restore_a', a))
            if b + 1 < N:
                candidates.append(('restore_b', b))

            for kind, param in candidates:
                if time.process_time() >= deadline:
                    break
                cand = best.copy()
                ok = True
                if kind == 'shift_whole':
                    d = param
                    if d < 0:
                        d = -d
                        for i in range(b - d + 1, b + 1):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(a - d, a):
                            if 0 <= i < N:
                                cand[i] = max(best[a], tiny)
                    else:
                        for i in range(a, a + d):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(b + 1, b + d + 1):
                            if 0 <= i < N:
                                cand[i] = max(best[b], tiny)
                elif kind == 'shrink_left':
                    k = param
                    for i in range(a, a + k):
                        cand[i] = max(best[a - 1] if a - 1 >= 0 else best[a], tiny)
                elif kind == 'shrink_right':
                    k = param
                    for i in range(b - k + 1, b + 1):
                        cand[i] = max(best[b + 1] if b + 1 < N else best[b], tiny)
                elif kind == 'expand_left':
                    k = param
                    for i in range(a - k, a):
                        cand[i] = 0.0
                elif kind == 'expand_right':
                    k = param
                    for i in range(b + 1, b + k + 1):
                        cand[i] = 0.0
                elif kind == 'zero_neighbor':
                    cand[param] = 0.0
                elif kind == 'restore_a':
                    if a - 1 >= 0:
                        cand[a] = max(best[a - 1], tiny)
                    else:
                        ok = False
                elif kind == 'restore_b':
                    if b + 1 < N:
                        cand[b] = max(best[b + 1], tiny)
                    else:
                        ok = False
                if not ok:
                    continue
                c0 = _C(cand)
                if c0 >= bestC:
                    continue
                hb, cb = _polish_candidate(cand, bestC)
                if hb is not None and cb < bestC - 1e-14:
                    best = hb
                    bestC = cb
                    accepted_any = True
                    break
            if accepted_any and time.process_time() >= deadline:
                break
        if not accepted_any:
            break
    return best, bestC


def _lp_high_polish(h, deadline, ps=(4096.0, 8192.0, 16384.0, 32768.0)):
    """High-p norm smoothing: closely approximates max, well-behaved gradient."""
    best = h.copy()
    bestC = _C(h)
    for p in ps:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _p=p):
            return _lp_obj(x, _p)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': 800, 'maxfun': 8000,
                                    'ftol': 1e-18, 'gtol': 1e-16})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _scaling_refine(h, deadline, rounds=4):
    """For fixed active set K, optimize over heights jointly with normalization
    using the exact rational structure: at optimum, h satisfies a linear
    condition.  We do a Newton-in-subspace step on the active variables."""
    N = len(h)
    best = h.copy()
    bestC = _C(h)
    for r in range(rounds):
        if time.process_time() >= deadline:
            break
        conv = _conv(h)
        M = float(conv.max())
        tol = 1e-7 * M
        K = np.where(conv >= M - tol)[0]
        if len(K) == 0 or len(K) > 0.9 * 2 * N:
            break
        # Build the linear system: for active k, sum_i h[i]*h[k-i] = M.
        # Unknowns: h (N), M (1), with sum h = S.  Solve least squares.
        # We use a small regularized solve with positivity clamp.
        A = np.zeros((len(K) + 1, N + 1))
        rhs = np.zeros(len(K) + 1)
        for row, k in enumerate(K):
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            for i in range(lo, hi + 1):
                A[row, i] += h[k - i]
            A[row, N] = -1.0
        A[-1, :N] = 1.0
        rhs[-1] = h.sum()
        try:
            sol, *_ = np.linalg.lstsq(A, rhs, rcond=None)
        except Exception:
            break
        cand = np.maximum(sol[:N], 0.0)
        s = cand.sum()
        if s <= 0:
            break
        cand /= s
        c = _C(cand)
        if c < bestC - 1e-15:
            bestC = c
            best = cand.copy()
            h = cand
        else:
            break
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Phase 1: high-p LP smoothing (approximates max tightly, smooth gradient)
    if time.process_time() < deadline:
        hb, cb = _lp_high_polish(best, min(deadline, time.process_time() + 0.30 * (deadline - time.process_time())))
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after LP-high: C=%.12f" % bestC)

    # Phase 2: active-set polish with progressively tighter tolerance
    for tol in (1e-4, 1e-6, 1e-8):
        if time.process_time() >= deadline:
            break
        slice_end = min(deadline, time.process_time() + 0.35 * (deadline - time.process_time()))
        hb, cb = _active_set_polish(best, slice_end, tol_rel=tol)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after active-set: C=%.12f" % bestC)

    # Phase 3: linear-system refinement on active set
    if time.process_time() < deadline:
        hb, cb = _scaling_refine(best, min(deadline, time.process_time() + 0.30 * (deadline - time.process_time())))
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after linear-refine: C=%.12f" % bestC)

    # Phase 4: boundary shift search (structural zeros)
    if time.process_time() < deadline:
        hb, cb = _boundary_shift_search(best, deadline, max_passes=2)
        if cb < bestC - 1e-14:
            bestC = cb
            best = hb.copy()
            print("after boundary shift: C=%.12f" % bestC)

    # Phase 5: fine N sweep around current size (only if time)
    Nc = len(best)
    if time.process_time() < deadline:
        lo = max(1, Nc - 20)
        hi = min(30000, Nc + 20)
        N_list = list(range(lo, hi + 1, 4))
        if Nc not in N_list:
            N_list.append(Nc)
        n_left = len(N_list)
        for N2 in N_list:
            now = time.process_time()
            if now >= deadline:
                break
            remaining = deadline - now
            n_left -= 1
            slice_deadline = now + remaining / max(1, n_left)
            h2 = _interp_to(best, N2)
            hb, cb = _active_set_polish(h2, slice_deadline, tol_rel=1e-6, maxiter=500)
            if cb < bestC:
                bestC = cb
                best = hb.copy()
    print("final: C=%.12f  N=%d" % (bestC, len(best)))

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0)):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h),
                           callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = np.convolve(h, h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6, maxiter=2000):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _adam_logspace(best, bestC, deadline, n_iter=4000):
    if time.process_time() >= deadline:
        return best, bestC
    hh = np.maximum(best.copy(), 0.0)
    N = len(hh)
    x = np.log(np.maximum(hh, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    lr0, lr1 = 0.003, 0.0002
    bestC2 = bestC
    best2 = hh.copy()
    for t in range(1, n_iter + 1):
        if time.process_time() >= deadline:
            break
        lr = lr0 + (lr1 - lr0) * (t - 1) / max(1, n_iter - 1)
        hcur = np.exp(x)
        S = hcur.sum()
        if S <= 0:
            break
        conv = np.convolve(hcur, hcur)
        cmax = conv.max()
        thr = cmax - 1e-9 * cmax
        active = np.where(conv >= thr)[0]
        C = 2.0 * N * cmax / (S * S)
        g = np.zeros(N)
        na = len(active)
        for k in active:
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            g[lo:hi + 1] += hcur[k - np.arange(lo, hi + 1)]
        g = g / na
        g = g * (2.0 * N) / (S * S) - (2.0 * C) / S
        gl = g * hcur
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        if t % 20 == 0:
            hc = np.exp(x)
            cc = _C(hc)
            if cc < bestC2:
                bestC2 = cc
                best2 = hc.copy()
    if bestC2 < bestC:
        return best2, bestC2
    return best, bestC


def _zero_runs(h, thresh):
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=3):
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    def _nearest_nonzero_height(arr, i):
        for d in range(1, N):
            if i - d >= 0 and arr[i - d] >= thresh:
                return arr[i - d]
            if i + d < N and arr[i + d] >= thresh:
                return arr[i + d]
        return tiny

    def _polish_candidate(cand, cur_bestC):
        if time.process_time() >= deadline:
            return None, cur_bestC
        hb, cb = _active_set_polish(cand, deadline, tol_rel=1e-4, maxiter=300)
        if cb >= cur_bestC:
            return None, cur_bestC
        if time.process_time() < deadline:
            hb2, cb2 = _active_set_polish(hb, deadline, tol_rel=1e-6, maxiter=300)
            if cb2 < cb:
                hb, cb = hb2, cb2
        if cb < cur_bestC - 1e-14:
            return hb, cb
        return None, cur_bestC

    def _apply_new_zero_interval(cand, a, b, na, nb):
        na = max(0, na)
        nb = min(N - 1, nb)
        if na <= nb:
            cand[na:nb + 1] = 0.0
        for i in range(a, b + 1):
            if i < na or i > nb:
                cand[i] = max(_nearest_nonzero_height(best, i), tiny)

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False

        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            for dl in range(-3, 4):
                if time.process_time() >= deadline:
                    break
                for dr in range(-3, 4):
                    if dl == 0 and dr == 0:
                        continue
                    if time.process_time() >= deadline:
                        break
                    cand = best.copy()
                    _apply_new_zero_interval(cand, a, b, a + dl, b + dr)
                    hb, cb = _polish_candidate(cand, bestC)
                    if hb is not None:
                        best = hb
                        bestC = cb
                        accepted_any = True
                        break
                if accepted_any:
                    break
            if accepted_any:
                break

        if not accepted_any:
            break

    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Try a few Ns around the seed's own N; each is polished + boundary-searched
    N0 = len(seed)
    Ns = sorted(set([max(2, int(N0 * f)) for f in (0.75, 1.0, 1.25, 1.5)]
                    + [N0]))
    Ns = [n for n in Ns if 2 <= n <= 30000]

    for Nn in Ns:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, Nn) if Nn != len(best) else best.copy()
        if h.sum() <= 0:
            h = np.ones(Nn)
        h = h / h.max()

        hb, cb = _polish_lbfgs(h, deadline,
                               betas=[200.0, 800.0, 3200.0, 12800.0])
        if cb < bestC:
            bestC = cb
            best = hb.copy()

        if time.process_time() < deadline:
            hb2, cb2 = _active_set_polish(best, deadline, tol_rel=1e-6,
                                          maxiter=2000)
            if cb2 < bestC:
                bestC = cb2
                best = hb2.copy()

        if time.process_time() < deadline:
            hb3, cb3 = _boundary_shift_search(best, deadline, max_passes=2)
            if cb3 < bestC:
                bestC = cb3
                best = hb3.copy()

    if time.process_time() < deadline:
        best, bestC = _adam_logspace(best, bestC, deadline, n_iter=3000)

    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-6, maxiter=3000)
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    if time.process_time() < deadline:
        hb, cb = _boundary_shift_search(best, deadline, max_passes=3)
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
