def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6, maxiter=3000):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _fast_active_grad(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.inf, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _quick_polish(h, deadline, tols=(1e-4, 1e-6), maxiter=300):
    best = h.copy()
    bestC = _C(h)
    for tol in tols:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _t=tol):
            return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _zero_runs(h, thresh):
    mask = h < thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _positive_runs(h, thresh):
    mask = h >= thresh
    runs = []
    N = len(h)
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _boundary_shift_search(h, deadline, max_passes=3):
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    def _try(cand, cur_bestC):
        if time.process_time() >= deadline:
            return None, cur_bestC
        c0 = _C(cand)
        if c0 >= cur_bestC:
            return None, cur_bestC
        hb, cb = _quick_polish(cand, deadline, tols=(1e-4, 1e-6), maxiter=250)
        if cb < cur_bestC - 1e-15:
            return hb, cb
        return None, cur_bestC

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        runs = _zero_runs(best, thresh)
        if not runs:
            break
        accepted_any = False
        for (a, b) in runs:
            if time.process_time() >= deadline:
                break
            candidates = []
            for d in range(1, 7):
                if a - d >= 0:
                    candidates.append(('shift', -d))
                if b + d < N:
                    candidates.append(('shift', d))
            for k in range(1, 4):
                if a + k - 1 <= b:
                    candidates.append(('shrink_l', k))
                if b - k + 1 >= a:
                    candidates.append(('shrink_r', k))
                if a - k >= 0:
                    candidates.append(('expand_l', k))
                if b + k < N:
                    candidates.append(('expand_r', k))
            if a - 1 >= 0:
                candidates.append(('zero_nb', a - 1))
            if b + 1 < N:
                candidates.append(('zero_nb', b + 1))
            if a - 1 >= 0:
                candidates.append(('restore_a', a))
            if b + 1 < N:
                candidates.append(('restore_b', b))

            for kind, param in candidates:
                if time.process_time() >= deadline:
                    break
                cand = best.copy()
                ok = True
                if kind == 'shift':
                    d = param
                    if d < 0:
                        d = -d
                        for i in range(b - d + 1, b + 1):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(a - d, a):
                            if 0 <= i < N:
                                cand[i] = max(best[a], tiny)
                    else:
                        for i in range(a, a + d):
                            if 0 <= i < N:
                                cand[i] = 0.0
                        for i in range(b + 1, b + d + 1):
                            if 0 <= i < N:
                                cand[i] = max(best[b], tiny)
                elif kind == 'shrink_l':
                    k = param
                    v = best[a - 1] if a - 1 >= 0 else best[a]
                    for i in range(a, a + k):
                        cand[i] = max(v, tiny)
                elif kind == 'shrink_r':
                    k = param
                    v = best[b + 1] if b + 1 < N else best[b]
                    for i in range(b - k + 1, b + 1):
                        cand[i] = max(v, tiny)
                elif kind == 'expand_l':
                    k = param
                    for i in range(a - k, a):
                        cand[i] = 0.0
                elif kind == 'expand_r':
                    k = param
                    for i in range(b + 1, b + k + 1):
                        cand[i] = 0.0
                elif kind == 'zero_nb':
                    cand[param] = 0.0
                elif kind == 'restore_a':
                    if a - 1 >= 0:
                        cand[a] = max(best[a - 1], tiny)
                    else:
                        ok = False
                elif kind == 'restore_b':
                    if b + 1 < N:
                        cand[b] = max(best[b + 1], tiny)
                    else:
                        ok = False
                if not ok:
                    continue
                hb, cb = _try(cand, bestC)
                if hb is not None and cb < bestC - 1e-15:
                    best = hb
                    bestC = cb
                    accepted_any = True
                    break
            if accepted_any and time.process_time() >= deadline:
                break
        if not accepted_any:
            break
    return best, bestC


def _topology_search(h, deadline, max_passes=2):
    """Try changing support topology: punch holes in positive runs, fill small zero runs."""
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0 or N < 3:
        return best, bestC
    thresh = 1e-9 * mx
    tiny = 1e-4 * mx

    def _try(cand, cur_bestC):
        if time.process_time() >= deadline:
            return None, cur_bestC
        c0 = _C(cand)
        if c0 >= cur_bestC:
            return None, cur_bestC
        hb, cb = _quick_polish(cand, deadline, tols=(1e-4, 1e-6), maxiter=250)
        if cb < cur_bestC - 1e-15:
            return hb, cb
        return None, cur_bestC

    for _pass in range(max_passes):
        if time.process_time() >= deadline:
            break
        accepted_any = False

        # Punch interior holes in each positive run.
        pos_runs = _positive_runs(best, thresh)
        for (a, b) in pos_runs:
            if time.process_time() >= deadline:
                break
            length = b - a + 1
            if length < 4:
                continue
            for w in range(1, 9):
                if w >= length - 1:
                    continue
                # offsets every 4 indices within interior
                max_off = length - w - 1
                if max_off < 1:
                    continue
                offs = list(range(1, max_off + 1, 4))
                if max_off not in offs:
                    offs.append(max_off)
                for off in offs:
                    if time.process_time() >= deadline:
                        break
                    s = a + off
                    e = s + w - 1
                    if s <= a or e >= b:
                        continue
                    cand = best.copy()
                    cand[s:e + 1] = 0.0
                    hb, cb = _try(cand, bestC)
                    if hb is not None and cb < bestC - 1e-15:
                        best = hb
                        bestC = cb
                        accepted_any = True
                        break
                if accepted_any:
                    break
            if accepted_any and time.process_time() >= deadline:
                break

        if accepted_any:
            continue

        # Fill small zero runs.
        zero_runs = _zero_runs(best, thresh)
        for (a, b) in zero_runs:
            if time.process_time() >= deadline:
                break
            w = b - a + 1
            if w > 8:
                continue
            left = best[a - 1] if a - 1 >= 0 else 0.0
            right = best[b + 1] if b + 1 < N else 0.0
            v = max(left, right, tiny)
            cand = best.copy()
            cand[a:b + 1] = v
            hb, cb = _try(cand, bestC)
            if hb is not None and cb < bestC - 1e-15:
                best = hb
                bestC = cb
                accepted_any = True
                break

        if not accepted_any:
            break

    return best, bestC


def _n_sweep(base, bestC, deadline, Ns):
    best = base.copy()
    n_left = len(Ns)
    for N2 in Ns:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slice_deadline = now + remaining / max(1, n_left)
        n_left -= 1
        h2 = _interp_to(best, N2)
        hb, cb = _quick_polish(h2, slice_deadline, tols=(1e-4, 1e-6), maxiter=600)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Reserve ~40% for N sweep, ~60% for L^p + polish + boundary + topology.
    sweep_start = t0 + budget_seconds * 0.90 * 0.58
    main_deadline = sweep_start

    # L^p polish
    hlp, clp = _lp_polish(best, main_deadline,
                          ps=(8.0, 32.0, 128.0, 512.0, 2048.0, 8192.0))
    if clp < bestC:
        bestC = clp
        best = hlp.copy()
    print("after L^p: C=%.9f" % bestC)

    # Active-set polish
    if time.process_time() < main_deadline:
        hb, cb = _active_set_polish(best, main_deadline, tol_rel=1e-4)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    if time.process_time() < main_deadline:
        hb, cb = _polish_lbfgs(best, main_deadline,
                               betas=(12000.0, 50000.0, 200000.0))
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after polish: C=%.9f" % bestC)

    # Boundary shift search
    shift_deadline = min(main_deadline,
                         time.process_time() + 0.70 * (main_deadline - time.process_time()))
    if time.process_time() < shift_deadline:
        hb, cb = _boundary_shift_search(best, shift_deadline, max_passes=3)
        if cb < bestC - 1e-12:
            bestC = cb
            best = hb.copy()
            print("after boundary shift: C=%.9f" % bestC)
        else:
            print("after boundary shift: no improvement (C=%.9f)" % bestC)

    # Topology pass: change number/placement of support components.
    topo_deadline = main_deadline
    if time.process_time() < topo_deadline:
        hb, cb = _topology_search(best, topo_deadline, max_passes=2)
        if cb < bestC - 1e-15:
            bestC = cb
            best = hb.copy()
            print("after topology: C=%.9f" % bestC)
        else:
            print("after topology: no improvement (C=%.9f)" % bestC)

    # N sweep: try nearby sizes plus coarser ones.
    Nc = len(best)
    Ns = []
    for d in range(-25, 26, 5):
        N2 = Nc + d
        if 1 <= N2 <= 30000 and N2 not in Ns:
            Ns.append(N2)
    for N2 in [Nc * 3 // 4, Nc * 2 // 3, Nc // 2, Nc * 5 // 4, Nc * 3 // 2]:
        if 1 <= N2 <= 30000 and N2 not in Ns:
            Ns.append(N2)
    Ns.sort(key=lambda x: abs(x - Nc))

    best, bestC = _n_sweep(best, bestC, deadline, Ns)

    # Final full polish
    if time.process_time() < deadline:
        hb, cb = _active_set_polish(best, deadline, tol_rel=1e-6, maxiter=800)
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("final C=%.9f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0),
                  maxiter=3000):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _lp_polish(h, deadline, ps=(8.0, 32.0, 128.0, 512.0, 2048.0)):
