def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _run_lbfgs(h, fun_factory, deadline, maxiter=2000):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return fun_factory(x)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()
        if time.process_time() >= deadline:
            raise StopIteration

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except StopIteration:
        pass
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _softmax_polish(h, deadline, betas, maxiter=2000):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        hb, cb = _run_lbfgs(best, lambda x, _b=beta: _softmax_obj(x, _b),
                            deadline, maxiter)
        if cb < bestC:
            bestC = cb
            best = hb
    return best, bestC


def _lp_polish(h, deadline, ps, maxiter=1500):
    best = h.copy()
    bestC = _C(h)
    for p in ps:
        if time.process_time() >= deadline:
            break
        hb, cb = _run_lbfgs(best, lambda x, _p=p: _lp_obj(x, _p),
                            deadline, maxiter)
        if cb < bestC:
            bestC = cb
            best = hb
    return best, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        x = np.linspace(-1, 1, 50)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Phase A: increase resolution and polish with softmax + Lp objectives.
    N0 = len(seed)
    Ns = sorted(set([N0, 2 * N0, 3 * N0, 1500, 3000]))
    Ns = [n for n in Ns if 50 <= n <= 30000]
    for N in Ns:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, N)
        if h.sum() <= 0:
            continue
        h = h / max(h.max(), 1e-12)
        hb, cb = _softmax_polish(h, deadline, [200.0, 1000.0, 4000.0, 16000.0])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
        hb, cb = _lp_polish(best, deadline, [8.0, 32.0, 128.0, 512.0])
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    # Phase B: high-beta softmax polish to sharpen the plateau.
    if time.process_time() < deadline:
        hb, cb = _softmax_polish(best, deadline,
                                 [50000.0, 200000.0, 800000.0], maxiter=1500)
        if cb < bestC:
            bestC = cb
            best = hb

    # Phase C: high-p Lp polish (approaches exact max).
    if time.process_time() < deadline:
        hb, cb = _lp_polish(best, deadline, [2048.0, 8192.0], maxiter=1500)
        if cb < bestC:
            bestC = cb
            best = hb

    # Phase D: final softmax touch.
    if time.process_time() < deadline:
        hb, cb = _softmax_polish(best, deadline, [3200000.0], maxiter=1000)
        if cb < bestC:
            bestC = cb
            best = hb

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 400:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _run_lbfgs(fun, x0, deadline, maxiter, callback):
    if time.process_time() >= deadline:
        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _polish(h, deadline, stages):
    best = h.copy()
    bestC = _C(h)
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        if kind == 'lp':
            def fun(x, _p=param):
                return _lp_obj(x, _p)
        elif kind == 'sm':
            def fun(x, _b=param):
                return _softmax_obj(x, _b)
        else:
            def fun(x, _t=param):
                return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 3000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _mirror_uncentered(h):
    nz = np.where(h > 0)[0]
    if nz.size == 0:
        return h.copy()
    a, b = nz[0], nz[-1]
    seg = h[a:b + 1]
    seg_sym = 0.5 * (seg + seg[::-1])
    out = np.zeros_like(h)
    out[a:b + 1] = seg_sym
    return out


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _sym_polish(h, deadline, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        x0 = h[:m].copy()
    else:
        x0 = h.copy()
    best_x = x0.copy()
    bestC = _C(_build_from_half(best_x, N, mode))

    stages = [('as', 1e-4), ('as', 1e-6),
              ('sm', 3000.0), ('sm', 12000.0),
              ('sm', 50000.0), ('sm', 200000.0)]
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best_x.copy(), 'bestC': bestC}

        if kind == 'as':
            def fun(x, _t=param):
                hh = _build_from_half(x, N, mode)
                cv, gfull = _active_set_obj(hh, _t)
                return cv, _sym_grad_chain(gfull, N, mode)
        else:
            def fun(x, _b=param):
                hh = _build_from_half(x, N, mode)
                J, gfull = _softmax_obj(hh, _b)
                return J, _sym_grad_chain(gfull, N, mode)

        def cb(xk):
            c = _C(_build_from_half(xk, N, mode))
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 2000, cb)
        c = _C(_build_from_half(xf, N, mode))
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best_x = state['best'].copy()
        bestC = state['bestC']

    return _build_from_half(best_x, N, mode), bestC


def _n_sweep(base, bestC, deadline, Ns):
    best = base.copy()
    n_left = max(1, len(Ns))
    for N2 in Ns:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slice_deadline = now + remaining / n_left
        n_left -= 1
        h2 = _interp_to(best, N2)
        hb, cb = _polish(h2, slice_deadline,
                         [('as', 1e-4), ('as', 1e-6), ('sm', 12000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    return best, bestC


# ---------- Exact reduced Newton on active set ----------

def _half_vars(h, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        return h[:m].copy()
    return h.copy()


def _newton_active(h, deadline, mode, tol_rel=1e-9, max_iter=40):
    """Exact reduced Newton step on the max plateau, symmetry-constrained."""
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
    else:
        m = N

    def build(x):
        return _build_from_half(x, N, mode)

    x = _half_vars(h, mode)
    hh = build(x)
    Cval = _C(hh)
    best_x = x.copy()
    best_C = Cval

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = _conv(hh)
        M = float(conv.max())
        tol = tol_rel * M
        K = np.where(conv >= M - tol)[0]
        if K.size == 0:
            break
        # gradient of C wrt full h
        ind = np.zeros(N)
        ind[K] = 1.0
        corr = np.convolve(ind, hh[::-1])
        gM = 2.0 * corr[N - 1: 2 * N - 1] / K.size
        gfull = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
        g = _sym_grad_chain(gfull, N, mode)

        # KKT residual: project onto nonnegativity
        nz = x > 1e-14
        # scale gradient to relative measure
        gscale = np.max(np.abs(g)) + 1e-30
        resid = np.where(nz, g, np.minimum(g, 0.0))
        res_norm = np.max(np.abs(resid)) / gscale
        if res_norm < 1e-12:
            break

        # Hessian of C wrt full h, then reduce to half vars.
        # C = 2N M / S^2, M = max conv (on plateau avg).
        # dM/dh_i = (2/K.size) * sum_{k in K} h_{k-i}  (correlation)
        # We use averaged gradient gM as dM/dh.
        # Hessian of M wrt h_i h_j: (2/K.size) * [ (i+j in K) ]  (since conv_k = sum h_a h_b, a+b=k)
        # Hessian of S^2 term: d/dh_j of -4NM/S^3 = -4N/S^3 dM/dh_j + 12NM/S^4
        # Full Hessian:
        # H_C[i,j] = (2N/S^2) * H_M[i,j]
        #          - (4N/S^3)(gM_i + gM_j)   [since dM/dh_i = gM_i, and d(1/S^2)/dh_j = -2/S^3]
        #          + (12 N M / S^4)
        # where H_M[i,j] = (2/K.size) * 1[(i+j) in K]
        Kset = np.zeros(2 * N - 1, dtype=bool)
        Kset[K] = True
        # Build H_M for full h (N x N). Only needed on half vars.
        # For centered mode: full index i, half index a: i=a for a<m, i=N-1-a for a>=m... 
        # We'll build full H_M (N x N) then reduce via chain matrix.
        # To save memory, build via index mapping.
        # H_M[i,j] = (2/K.size) * Kset[i+j]
        # Reduced: H_red[a,b] = sum_{i in pre(a), j in pre(b)} H_M[i,j] * w_i * w_j
        # where pre(a) is set of full indices mapping to half var a with weight w.
        # centered: a<m -> i=a (w=1); if N even, i=N-1-a (w=1); if odd and a<m-1, i=N-1-a (w=1)
        # uncentered: a -> i=a (w=0.5), i=N-1-a (w=0.5)
        # Build mapping lists
        if mode == 'centered':
            pre = []
            for a in range(m):
                lst = [(a, 1.0)]
                if N % 2 == 0:
                    lst.append((N - 1 - a, 1.0))
                else:
                    if a < m - 1:
                        lst.append((N - 1 - a, 1.0))
                pre.append(lst)
        else:
            pre = []
            for a in range(m):
                lst = [(a, 0.5)]
                b = N - 1 - a
                if b != a:
                    lst.append((b, 0.5))
                pre.append(lst)

        # Build reduced Hessian
        Hr = np.zeros((m, m))
        coef_M = 2.0 * N / (S * S) * (2.0 / K.size)
        coef_g = -4.0 * N / (S * S * S)
        coef_S = 12.0 * N * M / (S * S * S * S)
        for a in range(m):
            for b in range(m):
                s = 0.0
                for (i, wi) in pre[a]:
                    for (j, wj) in pre[b]:
                        if Kset[i + j]:
                            s += wi * wj
                Hr[a, b] = coef_M * s + coef_g * (g[a] + g[b]) + coef_S
        # symmetrize
        Hr = 0.5 * (Hr + Hr.T)

        # Solve Hr dx = -g with nonnegativity active set
        # active set: variables at 0 with g>0 stay fixed
        fixed = (x <= 1e-14) & (g > 0)
        free = ~fixed
        dx = np.zeros(m)
        if np.any(free):
            Hf = Hr[np.ix_(free, free)]
            gf = g[free]
            # regularize
            tr = np.trace(Hf) / max(1, Hf.shape[0])
            reg = 1e-12 * max(abs(tr), 1e-30)
            try:
                df = np.linalg.solve(Hf + reg * np.eye(Hf.shape[0]), -gf)
            except np.linalg.LinAlgError:
                df = -gf / (np.abs(np.diag(Hf)) + 1e-12)
            dx[free] = df
        # ensure descent
        slope = float(np.dot(g, dx))
        if slope >= 0:
            dx = -g / (np.abs(np.diag(Hr)) + 1e-12)
            slope = float(np.dot(g, dx))
        if slope >= 0:
            break

        # backtracking line search
        step = 1.0
        improved = False
        for _ in range(40):
            xn = x + step * dx
            xn = np.maximum(xn, 0.0)
            cn = _C(build(xn))
            if cn < Cval - 1e-16:
                x = xn
                Cval = cn
                improved = True
                if cn < best_C:
                    best_C = cn
                    best_x = xn.copy()
                break
            step *= 0.5
        if not improved:
            break

    return build(best_x), best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.9f (N=%d)" % (bestC, len(best)))

    # Phase 1: polish current solution
    phase1_end = t0 + budget_seconds * 0.35
    hb, cb = _polish(best, phase1_end,
                     [('lp', 32.0), ('lp', 128.0), ('lp', 512.0),
                      ('as', 1e-4), ('as', 1e-6),
                      ('sm', 12000.0), ('sm', 50000.0), ('sm', 200000.0)])
    if cb < bestC:
        bestC = cb
        best = hb.copy()
    print("after polish: C=%.9f" % bestC)

    # Phase 2: symmetry optimization
    sym_end = t0 + budget_seconds * 0.55
    if time.process_time() < sym_end:
        best_sym = best.copy()
        best_symC = bestC
        for mode in ('centered', 'uncentered'):
            if time.process_time() >= sym_end:
                break
            if mode == 'centered':
                hs = _mirror_centered(best)
            else:
                hs = _mirror_uncentered(best)
            hopt, copt = _sym_polish(hs, sym_end, mode)
            if copt < best_symC - 1e-15:
                best_symC = copt
                best_sym = hopt.copy()
                print("sym %s: C=%.9f" % (mode, copt))
        if best_symC < bestC - 1e-15:
            bestC = best_symC
            best = best_sym.copy()
    print("after symmetry: C=%.9f" % bestC)

    # Phase 3: N sweep (short)
    Nc = len(best)
    Ns = []
    for d in [0, -1, 1, -2, 2]:
        N2 = Nc + d
        if 1 <= N2 <= 30000 and N2 not in Ns:
            Ns.append(N2)
    Ns.sort(key=lambda x: abs(x - Nc))
    sweep_end = t0 + budget_seconds * 0.65
    best, bestC = _n_sweep(best, bestC, sweep_end, Ns)
    print("after N sweep: C=%.9f (N=%d)" % (bestC, len(best)))

    # Phase 4: exact reduced Newton on active set (the experiment)
    newton_end = t0 + budget_seconds * 0.88
    # Determine best symmetry mode for Newton
    best_newton = best.copy()
    best_newtonC = bestC
    for mode in ('centered', 'uncentered'):
        if time.process_time() >= newton_end:
            break
        if mode == 'centered':
            hs = _mirror_centered(best)
        else:
            hs = _mirror_uncentered(best)
        hn, cn = _newton_active(hs, newton_end, mode, tol_rel=1e-9)
        if cn < best_newtonC - 1e-15:
            best_newtonC = cn
            best_newton = hn.copy()
            print("newton %s: C=%.12f" % (mode, cn))
    if best_newtonC < bestC:
        bestC = best_newtonC
        best = best_newton.copy()

    # Phase 5: final polish
    final_end = deadline
    if time.process_time() < final_end:
        hb, cb = _polish(best, final_end,
                         [('as', 1e-8), ('sm', 800000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    print("final C=%.12f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

