    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _sym_polish(h, deadline, mode, stages=None):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        x0 = h[:m].copy()
    else:
        x0 = h.copy()
    best_x = x0.copy()
    bestC = _C(_build_from_half(best_x, N, mode))

    if stages is None:
        stages = [('as', 1e-4), ('as', 1e-6),
                  ('sm', 3000.0), ('sm', 12000.0),
                  ('sm', 50000.0), ('sm', 200000.0)]
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best_x.copy(), 'bestC': bestC}

        if kind == 'as':
            def fun(x, _t=param):
                hh = _build_from_half(x, N, mode)
                cv, gfull = _active_set_obj(hh, _t)
                return cv, _sym_grad_chain(gfull, N, mode)
        else:
            def fun(x, _b=param):
                hh = _build_from_half(x, N, mode)
                J, gfull = _softmax_obj(hh, _b)
                return J, _sym_grad_chain(gfull, N, mode)

        def cb(xk):
            c = _C(_build_from_half(xk, N, mode))
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 2000, cb)
        c = _C(_build_from_half(xf, N, mode))
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best_x = state['best'].copy()
        bestC = state['bestC']

    return _build_from_half(best_x, N, mode), bestC


def _conv_grad_matrix(h, K):
    N = len(h)
    rows = np.zeros((len(K), N))
    for r, k in enumerate(K):
        for i in range(N):
            a = k - i
            b = i - k
            v = 0.0
            if 0 <= a < N:
                v += h[a]
            if 0 <= b < N:
                v += h[b]
            rows[r, i] = v
    return rows


def _newton_step(h, deadline, max_iter=10, tol=1e-8):
    N = len(h)
    best = h.copy()
    bestC = _C(h)
    m = (N + 1) // 2
    mode = 'centered'

    def build(x):
        return _build_from_half(x, N, mode)

    x = h[:m].copy()
    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        conv = _conv(hh)
        M = float(conv.max())
        K = np.where(conv >= M - 1e-8 * M)[0]
        S = hh.sum()
        if S <= 0:
            break
        G = _conv_grad_matrix(hh, K)
        Jx = np.zeros((len(K), m))
        for j in range(m):
            Jx[:, j] = G[:, j]
            if N % 2 == 0:
                Jx[:, j] += G[:, N - 1 - j]
            else:
                if j < m - 1:
                    Jx[:, j] += G[:, N - 1 - j]
        sx = np.zeros(m)
        for j in range(m):
            sx[j] = 1.0
            if N % 2 == 0:
                sx[j] += 1.0
            else:
                if j < m - 1:
                    sx[j] += 1.0
        nres = len(K) + 1
        J = np.zeros((nres, m + 1))
        J[:len(K), :m] = Jx
        J[:len(K), m] = -1.0
        J[len(K), :m] = sx
        r = np.zeros(nres)
        r[:len(K)] = conv[K] - M
        r[len(K)] = S - 1.0
        try:
            dx, *_ = np.linalg.lstsq(J, -r, rcond=None)
        except Exception:
            break
        step_x = dx[:m]
        alpha = 1.0
        improved = False
        for _ in range(30):
            xn = x + alpha * step_x
            xn = np.maximum(xn, 0.0)
            hn = build(xn)
            cn = _C(hn)
            if cn < bestC - 1e-15:
                x = xn
                best = hn
                bestC = cn
                improved = True
                break
            alpha *= 0.5
        if not improved:
            break
        if np.linalg.norm(step_x) < tol:
            break
    return best, bestC


def _merge_compress(h, deadline, tol=1e-12):
    """Greedy adjacent merge by length-weighted averaging, accept if C increase < tol."""
    h = np.asarray(h, dtype=float).copy()
    bestC = _C(h)
    # lengths of each interval (equal widths initially)
    lengths = np.ones(len(h))
    improved = True
    while improved:
        improved = False
        n = len(h)
        if n <= 2:
            break
        if time.process_time() >= deadline:
            break
        # try merges; pick the best (smallest C) accepted merge
        best_merge = None
        best_merge_C = None
        # evaluate all candidate merges cheaply: only accept if C increase small
        # to save time, evaluate in order and take first acceptable
        for i in range(n - 1):
            if time.process_time() >= deadline:
                break
            new_len = lengths[i] + lengths[i + 1]
            new_val = (h[i] * lengths[i] + h[i + 1] * lengths[i + 1]) / new_len
            hn = np.concatenate([h[:i], [new_val], h[i + 2:]])
            cn = _C(hn)
            if cn <= bestC + tol:
                if best_merge_C is None or cn < best_merge_C:
                    best_merge_C = cn
                    best_merge = (i, hn, new_len)
        if best_merge is not None:
            i, hn, new_len = best_merge
            h = hn
            lengths = np.concatenate([lengths[:i], [new_len], lengths[i + 2:]])
            bestC = best_merge_C
            improved = True
    return h, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.9f (N=%d)" % (bestC, len(best)))

    N0 = len(best)
    candidates = [best.copy()]

    # Continuation: interpolate to 2N and 4N, run Newton + light polish
    for mult, frac in [(2, 0.30), (4, 0.55)]:
        if time.process_time() >= deadline:
            break
        N2 = min(30000, N0 * mult)
        if N2 == N0:
            continue
        h2 = _interp_to(best, N2)
        h2 = _mirror_centered(h2)
        sub_deadline = t0 + budget_seconds * frac
        hn, cn = _newton_step(h2, sub_deadline, max_iter=12)
        print("newton N=%d: C=%.9f" % (len(hn), cn))
        if time.process_time() < sub_deadline:
            hp, cp = _sym_polish(hn, sub_deadline, 'centered',
                                 stages=[('as', 1e-6), ('sm', 12000.0),
                                         ('sm', 50000.0)])
            if cp < cn:
                hn, cn = hp, cp
                print("polish N=%d: C=%.9f" % (len(hn), cn))
        candidates.append(hn)
        if cn < bestC:
            bestC = cn
            best = hn.copy()

    # Compress each high-N candidate via adaptive knot merging
    comp_end = t0 + budget_seconds * 0.85
    best_comp = best.copy()
    best_compC = bestC
    for cand in candidates:
        if time.process_time() >= comp_end:
            break
        hc, cc = _merge_compress(cand, comp_end, tol=1e-12)
        print("compress N=%d->%d: C=%.9f" % (len(cand), len(hc), cc))
        if cc < best_compC:
            best_compC = cc
            best_comp = hc.copy()

    if best_compC < bestC:
        best = best_comp
        bestC = best_compC

    # Final quick polish on best
    if time.process_time() < deadline:
        hp, cp = _sym_polish(best, deadline, 'centered',
                             stages=[('as', 1e-6), ('sm', 50000.0)])
        if cp < bestC:
            best, bestC = hp, cp

    print("final C=%.9f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _polish_lbfgs(h, deadline, betas=(50.0, 200.0, 800.0, 3000.0, 12000.0),
                  maxiter=3000):
    best = h.copy()
    bestC = _C(h)
    for beta in betas:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _lp_polish(h, deadline, ps=(8.0, 32.0, 128.0, 512.0, 2048.0)):
    best = h.copy()
    bestC = _C(h)
    for p in ps:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _p=p):
            return _lp_obj(x, _p)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': 2000, 'maxfun': 20000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    gM = np.zeros(N)
    invK = 1.0 / len(K)
    for k in K:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        gM[idx] += 2.0 * h[k - idx]
    gM *= invK
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _active_set_polish(h, deadline, tol_rel=1e-6, maxiter=3000):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _quick_polish(h, deadline, tols=(1e-4, 1e-6), maxiter=300):
    best = h.copy()
    bestC = _C(h)
    for tol in tols:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        def fun(x, _t=tol):
            return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        try:
            res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * len(h), callback=cb,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            xf = res.x
        except Exception:
            xf = state['best']
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


# ---------------- Rich B-spline family (M=64, free endpoint a) ----------------
# Symmetric cubic B-spline on support [-a, a], a in (0, 0.25].
# Coefficients parameterized as log(c) so positivity is automatic.
# We evaluate on a fixed fine grid and optimize (log a, log c_0..c_{M-1}).

def _bspline_basis(K, t):
    """Cubic B-spline basis on [0,1] with K control points, clamped knots."""
    from scipy.interpolate import BSpline
    n_int = K - 4
    if n_int < 1:
        n_int = 1
    knots = np.concatenate([[0.0]*4, np.linspace(0, 1, n_int+2)[1:-1], [1.0]*4])
    if len(knots) != K + 4:
        knots = np.linspace(0, 1, K + 4)
    basis = np.zeros((len(t), K))
    for i in range(K):
        c = np.zeros(K)
        c[i] = 1.0
        try:
            sp = BSpline(knots, c, 3, extrapolate=False)
            v = sp(t)
            v = np.where(np.isfinite(v), v, 0.0)
            basis[:, i] = v
        except Exception:
            basis[:, i] = 0.0
    return basis


def _spline_eval_from_log(params, N):
    """params = [log_a, log_c_0..log_c_{M-1}]. Returns h of length N."""
    M = len(params) - 1
    a = np.exp(params[0])
    if a <= 0 or a > 0.25:
        a = min(max(a, 1e-4), 0.25)
    c = np.exp(np.clip(params[1:], -50.0, 50.0))
    x = np.linspace(-0.25, 0.25, N)
    t = (x + a) / (2 * a)
    t = np.clip(t, 0.0, 1.0)
    B = _bspline_basis(M, t)
    h = B @ c
    mask = (x >= -a) & (x <= a)
    h = np.where(mask, h, 0.0)
    h = np.maximum(h, 0.0)
    return h


def _rich_spline_fit(start_h, deadline, N=2000, M=64):
    """Fit rich symmetric cubic B-spline with M control points and free endpoint a."""
    from scipy.optimize import minimize as _min
    # Initialize from start_h: downsample to M points
    Ms = len(start_h)
    xp = np.linspace(0.0, 1.0, Ms)
    xk = np.linspace(0.0, 1.0, M)
    c0 = np.interp(xk, xp, start_h)
    c0 = 0.5 * (c0 + c0[::-1])
    c0 = np.maximum(c0, 1e-6)
    # Estimate a from support
    mx = start_h.max()
    if mx > 0:
        nz = np.where(start_h > 1e-6 * mx)[0]
        if len(nz) > 0:
            lo = -0.25 + 0.5 * nz[0] / (Ms - 1)
            hi = -0.25 + 0.5 * nz[-1] / (Ms - 1)
            a0 = 0.5 * (hi - lo)
        else:
            a0 = 0.25
    else:
        a0 = 0.25
    a0 = min(max(a0, 0.01), 0.25)
    params0 = np.concatenate([[np.log(a0)], np.log(c0)])

    best_params = params0.copy()
    best_h = _spline_eval_from_log(best_params, N)
    bestC = _C(best_h)

    # Bounds: log_a in [log(0.01), log(0.25)], log_c in [-50, 50]
    bounds = [(np.log(0.01), np.log(0.25))] + [(-50.0, 50.0)] * M

    # Phase A: differential evolution with small population on a coarse grid
    # to escape local basin. Use N=400 for speed.
    Ncoarse = 400

    def de_obj(p):
        h = _spline_eval_from_log(p, Ncoarse)
        return _C(h)

    try:
        de_res = differential_evolution(
            de_obj, bounds, maxiter=30, popsize=8, tol=1e-6,
            mutation=(0.5, 1.0), recombination=0.7, seed=12345,
            polish=False, init='latinhypercube', workers=1)
        p_de = de_res.x
        h_de = _spline_eval_from_log(p_de, N)
        c_de = _C(h_de)
        if c_de < bestC:
            bestC = c_de
            best_params = p_de.copy()
            print("DE improved: C=%.9f" % bestC)
    except Exception as e:
        print("DE failed: %s" % e)

    # Phase B: L-BFGS with numerical gradient on fine grid N
    if time.process_time() < deadline:
        def fun(p):
            h = _spline_eval_from_log(p, N)
            return _C(h)

        state = {'best': best_params.copy(), 'bestC': bestC}

        def cb(pk):
            hh = _spline_eval_from_log(pk, N)
            c = _C(hh)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = pk.copy()

        try:
            res = _min(fun, best_params, method='L-BFGS-B', bounds=bounds,
                       callback=cb,
                       options={'maxiter': 200, 'maxfun': 4000,
                                'ftol': 1e-16, 'gtol': 1e-12})
            pf = res.x
            hh = _spline_eval_from_log(pf, N)
            c = _C(hh)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = pf.copy()
        except Exception as e:
            print("L-BFGS failed: %s" % e)
        best_params = state['best'].copy()
        bestC = state['bestC']

    best_h = _spline_eval_from_log(best_params, N)
    bestC = _C(best_h)
    return best_h, bestC


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 50
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.9f (N=%d)" % (bestC, len(best)))

    # ---- Phase 1: rich B-spline family fit (M=64, free endpoint) ----
    spline_deadline = t0 + budget_seconds * 0.90 * 0.55
    try:
        h_sp, c_sp = _rich_spline_fit(best, spline_deadline, N=2000, M=64)
        print("rich spline fit: C=%.9f" % c_sp)
        if c_sp < bestC - 1e-12:
            # polish with active set on the resampled shape
            polish_deadline = min(deadline, time.process_time() + budget_seconds * 0.90 * 0.15)
            hb, cb = _quick_polish(h_sp, polish_deadline, tols=(1e-4, 1e-6), maxiter=600)
            if cb < c_sp:
                c_sp = cb
                h_sp = hb
            print("rich spline polished: C=%.9f" % c_sp)
            if c_sp < bestC - 1e-12:
