import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _polish(h, deadline, tol_rel=1e-7, maxiter=500):
    state = {'best': h.copy(), 'bestC': _C(h)}

    def fun(x):
        return _active_set_obj(x, tol_rel)

    def cb(xk):
        c = _C(xk)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xk.copy()

    try:
        res = minimize(fun, state['best'], jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h), callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-18, 'gtol': 1e-16})
        xf = res.x
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    except Exception:
        pass
    return state['best'].copy(), state['bestC']


def _kkt_refine(h, deadline, max_rounds=8, tol_rel=1e-7, maxiter=400):
    best = h.copy()
    bestC = _C(h)
    for _ in range(max_rounds):
        if time.process_time() >= deadline:
            break
        hb, cb = _polish(best, deadline, tol_rel=tol_rel, maxiter=maxiter)
        if cb < bestC - 1e-16:
            best, bestC = hb, cb
        else:
            break
    return best, bestC


def _refine_at_N(h, N, deadline, max_rounds=8):
    h2 = _interp_to(h, N)
    hb, cb = _kkt_refine(h2, deadline, max_rounds=max_rounds,
                         tol_rel=1e-7, maxiter=500)
    return hb, cb


def _punch_holes(h, deadline, max_w=6):
    """Try zeroing short interior segments to find better topology."""
    best = h.copy()
    bestC = _C(best)
    N = len(best)
    mx = best.max()
    if mx <= 0:
        return best, bestC
    thresh = 1e-9 * mx
    mask = best >= thresh
    runs = []
    i = 0
    while i < N:
        if mask[i]:
            j = i
            while j + 1 < N and mask[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    for (a, b) in runs:
        if time.process_time() >= deadline:
            break
        L = b - a + 1
        if L < 4:
            continue
        for w in range(1, max_w + 1):
            if time.process_time() >= deadline:
                break
            if w >= L - 1:
                continue
            step = max(1, (L - w) // 8)
            for off in range(1, L - w, step):
                if time.process_time() >= deadline:
                    break
                s = a + off
                e = s + w - 1
                if s <= a or e >= b:
                    continue
                cand = best.copy()
                cand[s:e + 1] = 0.0
                if _C(cand) >= bestC:
                    continue
                hb, cb = _kkt_refine(cand, deadline, max_rounds=4,
                                     tol_rel=1e-7, maxiter=250)
                if cb < bestC - 1e-16:
                    best, bestC = hb, cb
                    break
            if time.process_time() >= deadline:
                break
    return best, bestC


def _smooth_resample(h, N):
    """Resample onto N points using a smooth (triangular) kernel, then
    renormalize. Helps escape the discrete grid without sharp artifacts."""
    M = len(h)
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    # linear interp as base
    base = np.interp(x, xp, h)
    # light smoothing on the fine grid
    if N >= 5:
        k = np.array([0.25, 0.5, 0.25])
        sm = np.convolve(base, k, mode='same')
        # keep endpoints reasonable
        sm[0] = base[0]
        sm[-1] = base[-1]
        base = np.maximum(sm, 0.0)
    return base


def _jitter(h, rng, scale):
    """Perturb h multiplicatively with small random noise, clip to >=0."""
    noise = 1.0 + scale * (rng.random(len(h)) - 0.5) * 2.0
    return np.maximum(h * noise, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 200
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    N0 = len(best)
    print("start C=%.9f (N=%d)" % (bestC, N0))

    # Polish the start at its own resolution.
    if time.process_time() < deadline:
        hb, cb = _kkt_refine(best, deadline, max_rounds=6, tol_rel=1e-7,
                             maxiter=400)
        if cb < bestC:
            best, bestC = hb, cb
        print("polished start C=%.9f" % bestC)

    # Try refining at higher resolutions using smooth resampling.
    for mult in (2, 4, 8):
        if time.process_time() >= deadline:
            break
        Nbig = N0 * mult
        if Nbig > 30000:
            break
        now = time.process_time()
        remaining = deadline - now
        slice_deadline = now + remaining * 0.4
        hbig = _smooth_resample(best, Nbig)
        hbig, cbig = _kkt_refine(hbig, slice_deadline, max_rounds=6,
                                 tol_rel=1e-7, maxiter=500)
        print("N=%d refine: C=%.9f (was %.9f)" % (Nbig, cbig, bestC))
        if cbig < bestC - 1e-16:
            best, bestC = hbig, cbig

    # Hole-punching search for topology improvement.
    if time.process_time() < deadline:
        hb, cb = _punch_holes(best, deadline, max_w=6)
        if cb < bestC:
            best, bestC = hb, cb
            print("after holes C=%.9f (N=%d)" % (bestC, len(best)))

    # Jitter-based local search: perturb and re-polish.
    if time.process_time() < deadline:
        scales = [2e-3, 1e-3, 5e-4, 2e-4, 1e-4]
        tries = 0
        while time.process_time() < deadline * 0.98:
            sc = scales[tries % len(scales)]
            tries += 1
            cand = _jitter(best, rng, sc)
            if cand.sum() <= 0:
                continue
            now = time.process_time()
            remaining = deadline - now
            if remaining <= 0:
                break
            slice_deadline = now + min(remaining * 0.5, 1.5)
            hb, cb = _kkt_refine(cand, slice_deadline, max_rounds=3,
                                 tol_rel=1e-7, maxiter=300)
            if cb < bestC - 1e-16:
                best, bestC = hb, cb
                print("jitter C=%.9f (N=%d, sc=%.1e)" % (bestC, len(best), sc))

    # Final tight polish.
    if time.process_time() < deadline:
        hb, cb = _kkt_refine(best, deadline, max_rounds=8, tol_rel=1e-7,
                             maxiter=500)
        if cb < bestC:
            best, bestC = hb, cb

    print("final C=%.9f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

