        # bump near where h contributes to that max
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if hi > lo and rng.rand() < 0.5:
            c = rng.randint(lo, hi + 1)
            w = max(1, N // 40)
            a = max(0, c - w)
            b = min(N, c + w + 1)
            cand[a:b] *= (1.0 + rng.uniform(-0.1, 0.2))
