    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _run_lbfgs(fun, x0, deadline, maxiter, callback):
    if time.process_time() >= deadline:
        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _polish(h, deadline, stages):
    best = h.copy()
    bestC = _C(h)
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        if kind == 'lp':
            def fun(x, _p=param):
                return _lp_obj(x, _p)
        elif kind == 'sm':
            def fun(x, _b=param):
                return _softmax_obj(x, _b)
        else:
            def fun(x, _t=param):
                return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 3000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _mirror_uncentered(h):
    nz = np.where(h > 0)[0]
    if nz.size == 0:
        return h.copy()
    a, b = nz[0], nz[-1]
    seg = h[a:b + 1]
    seg_sym = 0.5 * (seg + seg[::-1])
    out = np.zeros_like(h)
    out[a:b + 1] = seg_sym
    return out


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _sym_polish(h, deadline, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        x0 = h[:m].copy()
    else:
        x0 = h.copy()
    best_x = x0.copy()
    bestC = _C(_build_from_half(best_x, N, mode))

    stages = [('as', 1e-4), ('as', 1e-6),
              ('sm', 3000.0), ('sm', 12000.0),
              ('sm', 50000.0), ('sm', 200000.0)]
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best_x.copy(), 'bestC': bestC}

        if kind == 'as':
            def fun(x, _t=param):
                hh = _build_from_half(x, N, mode)
                cv, gfull = _active_set_obj(hh, _t)
                return cv, _sym_grad_chain(gfull, N, mode)
        else:
            def fun(x, _b=param):
                hh = _build_from_half(x, N, mode)
                J, gfull = _softmax_obj(hh, _b)
                return J, _sym_grad_chain(gfull, N, mode)

        def cb(xk):
            c = _C(_build_from_half(xk, N, mode))
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 2000, cb)
        c = _C(_build_from_half(xf, N, mode))
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best_x = state['best'].copy()
        bestC = state['bestC']

    return _build_from_half(best_x, N, mode), bestC


def _n_sweep(base, bestC, deadline, Ns):
    best = base.copy()
    n_left = max(1, len(Ns))
    for N2 in Ns:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slice_deadline = now + remaining / n_left
        n_left -= 1
        h2 = _interp_to(best, N2)
        hb, cb = _polish(h2, slice_deadline,
                         [('as', 1e-4), ('as', 1e-6), ('sm', 12000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    return best, bestC


# ---------- Exact reduced Newton on active set ----------

def _half_vars(h, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        return h[:m].copy()
    return h.copy()


def _newton_active(h, deadline, mode, tol_rel=1e-9, max_iter=40, freeze_zeros=False):
    """Exact reduced Newton step on the max plateau, symmetry-constrained."""
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
    else:
        m = N

    def build(x):
        return _build_from_half(x, N, mode)

    x = _half_vars(h, mode)
    hh = build(x)
    Cval = _C(hh)
    best_x = x.copy()
    best_C = Cval

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = _conv(hh)
        M = float(conv.max())
        tol = tol_rel * M
        K = np.where(conv >= M - tol)[0]
        if K.size == 0:
            break
        ind = np.zeros(N)
        ind[K] = 1.0
        corr = np.convolve(ind, hh[::-1])
        gM = 2.0 * corr[N - 1: 2 * N - 1] / K.size
        gfull = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
        g = _sym_grad_chain(gfull, N, mode)

        nz = x > 1e-14
        gscale = np.max(np.abs(g)) + 1e-30
        resid = np.where(nz, g, np.minimum(g, 0.0))
        res_norm = np.max(np.abs(resid)) / gscale
        if res_norm < 1e-12:
            break

        Kset = np.zeros(2 * N - 1, dtype=bool)
        Kset[K] = True
        if mode == 'centered':
            pre = []
            for a in range(m):
                lst = [(a, 1.0)]
                if N % 2 == 0:
                    lst.append((N - 1 - a, 1.0))
                else:
                    if a < m - 1:
                        lst.append((N - 1 - a, 1.0))
                pre.append(lst)
        else:
            pre = []
            for a in range(m):
                lst = [(a, 0.5)]
                b = N - 1 - a
                if b != a:
                    lst.append((b, 0.5))
                pre.append(lst)

        Hr = np.zeros((m, m))
        coef_M = 2.0 * N / (S * S) * (2.0 / K.size)
        coef_g = -4.0 * N / (S * S * S)
        coef_S = 12.0 * N * M / (S * S * S * S)
        for a in range(m):
            for b in range(m):
                s = 0.0
                for (i, wi) in pre[a]:
                    for (j, wj) in pre[b]:
                        if Kset[i + j]:
                            s += wi * wj
                Hr[a, b] = coef_M * s + coef_g * (g[a] + g[b]) + coef_S
        Hr = 0.5 * (Hr + Hr.T)

        if freeze_zeros:
            fixed = (x <= 1e-14)
        else:
            fixed = (x <= 1e-14) & (g > 0)
        free = ~fixed
        dx = np.zeros(m)
        if np.any(free):
            Hf = Hr[np.ix_(free, free)]
            gf = g[free]
            tr = np.trace(Hf) / max(1, Hf.shape[0])
            reg = 1e-12 * max(abs(tr), 1e-30)
            try:
                df = np.linalg.solve(Hf + reg * np.eye(Hf.shape[0]), -gf)
            except np.linalg.LinAlgError:
                df = -gf / (np.abs(np.diag(Hf)) + 1e-12)
            dx[free] = df
        slope = float(np.dot(g, dx))
        if slope >= 0:
            dx = -g / (np.abs(np.diag(Hr)) + 1e-12)
            slope = float(np.dot(g, dx))
        if slope >= 0:
            break

        step = 1.0
        improved = False
        for _ in range(40):
            xn = x + step * dx
            xn = np.maximum(xn, 0.0)
            cn = _C(build(xn))
            if cn < Cval - 1e-16:
                x = xn
                Cval = cn
                improved = True
                if cn < best_C:
                    best_C = cn
                    best_x = xn.copy()
                break
            step *= 0.5
        if not improved:
            break

    return build(best_x), best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.9f (N=%d)" % (bestC, len(best)))

    # ===== EXPERIMENT: interpolate to N=1600, symmetrize, Newton with free zeros =====
    N1 = 1600
    h1 = _interp_to(best, N1)
    h1 = _mirror_centered(h1)
    c1 = _C(h1)
    print("interp N=%d: C=%.12f" % (N1, c1))

    newton_end = t0 + budget_seconds * 0.55
    hn, cn = _newton_active(h1, newton_end, 'centered', tol_rel=1e-11,
                            max_iter=120, freeze_zeros=False)
    print("newton centered N=%d: C=%.12f" % (len(hn), cn))

    # prune tiny entries, re-run Newton on reduced support
    mx = hn.max()
    if mx > 0:
        keep = hn >= 1e-12 * mx
        nz = np.where(keep)[0]
        if nz.size > 0:
            a, b = nz[0], nz[-1]
            hp = np.zeros_like(hn)
            hp[a:b + 1] = hn[a:b + 1]
            hp = _mirror_centered(hp)
            cp = _C(hp)
            if time.process_time() < newton_end:
                hp2, cp2 = _newton_active(hp, newton_end, 'centered',
                                          tol_rel=1e-11, max_iter=120,
                                          freeze_zeros=False)
                if cp2 < cp:
                    hp, cp = hp2, cp2
            if cp < cn:
                hn, cn = hp, cp
    print("after prune+newton: C=%.12f (N=%d)" % (cn, len(hn)))

    if cn < bestC:
        bestC = cn
        best = hn.copy()

    # polish with softmax
    polish_end = t0 + budget_seconds * 0.80
    if time.process_time() < polish_end:
        hb, cb = _polish(best, polish_end, [('sm', 200000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after polish: C=%.12f (N=%d)" % (bestC, len(best)))

    # final short polish with remaining budget
    final_end = deadline
    if time.process_time() < final_end:
        hb, cb = _polish(best, final_end, [('sm', 500000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    print("final C=%.12f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 400:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _run_lbfgs(fun, x0, deadline, maxiter, callback):
    if time.process_time() >= deadline:
        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _polish(h, deadline, stages):
    best = h.copy()
    bestC = _C(h)
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        if kind == 'lp':
            def fun(x, _p=param):
                return _lp_obj(x, _p)
        elif kind == 'sm':
            def fun(x, _b=param):
                return _softmax_obj(x, _b)
        else:
            def fun(x, _t=param):
                return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 3000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _lp_obj(h, p):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    m = float(conv.max())
    if m <= 0:
        return 1e18, np.zeros(N)
    u = conv / m
    up = u ** p
    Z = float(up.sum())
    if Z <= 0:
        return 1e18, np.zeros(N)
    Zp = Z ** (1.0 / p)
    J = m * Zp / (S * S)
    coef = m * (Z ** (1.0 / p - 1.0)) / (S * S)
    w = coef * (u ** (p - 1.0))
    corr = np.convolve(w, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv - 2.0 * J / S
    return J, grad


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _half_vars(h, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        return h[:m].copy()
    return h.copy()


def _newton_active_cg(h, deadline, mode, tol_rel=1e-8, max_iter=60):
    N = len(h)
    m = (N + 1) // 2 if mode == 'centered' else N

    def build(x):
        return _build_from_half(x, N, mode)

    x = _half_vars(h, mode)
    best_x = x.copy()
    best_C = _C(build(x))

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = _conv(hh)
        M = float(conv.max())
        tol = tol_rel * M
        K = np.where(conv >= M - tol)[0]
        if K.size == 0:
            break
        ind = np.zeros(N)
        ind[K] = 1.0
        corr = np.convolve(ind, hh[::-1])
        gM = 2.0 * corr[N - 1: 2 * N - 1] / K.size
        gfull = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
        g = _sym_grad_chain(gfull, N, mode)

        nz = x > 1e-14
        gscale = np.max(np.abs(g)) + 1e-30
        resid = np.where(nz, g, np.minimum(g, 0.0))
        if np.max(np.abs(resid)) / gscale < 1e-13:
            break

        Kset = np.zeros(2 * N - 1, dtype=bool)
        Kset[K] = True
        if mode == 'centered':
            pre = []
            for a in range(m):
                lst = [(a, 1.0)]
                if N % 2 == 0:
                    lst.append((N - 1 - a, 1.0))
                elif a < m - 1:
                    lst.append((N - 1 - a, 1.0))
                pre.append(lst)
        else:
            pre = []
            for a in range(m):
                lst = [(a, 0.5)]
                b = N - 1 - a
                if b != a:
                    lst.append((b, 0.5))
                pre.append(lst)

        coef_M = 2.0 * N / (S * S) * (2.0 / K.size)
        coef_g = -4.0 * N / (S * S * S)
        coef_S = 12.0 * N * M / (S * S * S * S)

        def Hv(v):
            u = np.zeros(m)
            u[:] = v
            if mode == 'centered':
                dfull = np.zeros(N)
                dfull[:m] = u
                if N % 2 == 0:
                    dfull[m:] = u[:m][::-1]
                else:
                    dfull[m:] = u[:m - 1][::-1]
            else:
                dfull = 0.5 * (u + u[::-1])
            L = 2 * N - 1
            R = np.correlate(dfull, Kset.astype(float), mode='full')
            Rfull = np.zeros(N)
            for i in range(N):
                Rfull[i] = R[L - 1 - i]
            Hu = np.zeros(m)
            for a in range(m):
                s = 0.0
                for (i, wi) in pre[a]:
                    s += wi * Rfull[i]
                Hu[a] = s
            sum_u = float(np.sum(u))
            gu = float(np.dot(g, u))
            Hu = coef_M * Hu + coef_g * (g * sum_u + gu) + coef_S * sum_u
            return Hu

        fixed = (x <= 1e-14) & (g > 0)
        free = ~fixed
        dx = np.zeros(m)
        if np.any(free):
            def Hv_free(v):
                u = np.zeros(m)
                u[free] = v
                return Hv(u)[free]
            gf = g[free]
            nf = gf.size
            d = np.zeros(nf)
            r = -gf.copy()
            p = r.copy()
            rs = float(np.dot(r, r))
            for _cg in range(min(nf, 200)):
                if time.process_time() >= deadline:
                    break
                Hp = Hv_free(p)
                denom = float(np.dot(p, Hp))
                if denom <= 1e-30:
                    break
                alpha = rs / denom
                d += alpha * p
                r -= alpha * Hp
                rs_new = float(np.dot(r, r))
                if rs_new < 1e-24 * rs:
                    break
                beta = rs_new / rs
                p = r + beta * p
                rs = rs_new
            dx[free] = d

        slope = float(np.dot(g, dx))
        if slope >= 0:
            dx = -g / (np.abs(g) + 1e-12)
            slope = float(np.dot(g, dx))
        if slope >= 0:
            break

        step = 1.0
        improved = False
        cur_C = _C(build(x))
        for _ in range(40):
            xn = np.maximum(x + step * dx, 0.0)
            cn = _C(build(xn))
            if cn < cur_C - 1e-16:
                x = xn
                if cn < best_C:
                    best_C = cn
                    best_x = xn.copy()
                improved = True
                break
            step *= 0.5
        if not improved:
            break

    return build(best_x), best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.9f (N=%d)" % (bestC, len(best)))

    # Upsample to N=4000 and symmetrize
    N_target = 4000
    h4 = _interp_to(best, N_target)
    h4 = _mirror_centered(h4)
    c4 = _C(h4)
    print("upsampled C=%.9f (N=%d)" % (c4, len(h4)))

    # Matrix-free reduced Newton with centered symmetry
    hn, cn = _newton_active_cg(h4, deadline, 'centered', tol_rel=1e-10, max_iter=80)
    print("newton centered: C=%.12f" % cn)
    if cn < bestC:
        bestC = cn
        best = hn.copy()

    # Prune tiny entries
    mx = best.max()
    if mx > 0:
        best = np.where(best < 1e-12 * mx, 0.0, best)
    bestC = _C(best)
    print("after prune: C=%.12f (N=%d)" % (bestC, len(best)))

    # Final polish with softmax
    if time.process_time() < deadline:
        hb, cb = _polish(best, deadline, [('sm', 200000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    print("final C=%.12f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

