        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _polish(h, deadline, stages):
    best = h.copy()
    bestC = _C(h)
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        if kind == 'lp':
            def fun(x, _p=param):
                return _lp_obj(x, _p)
        elif kind == 'sm':
            def fun(x, _b=param):
                return _softmax_obj(x, _b)
        else:
            def fun(x, _t=param):
                return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 3000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _mirror_uncentered(h):
    nz = np.where(h > 0)[0]
    if nz.size == 0:
        return h.copy()
    a, b = nz[0], nz[-1]
    seg = h[a:b + 1]
    seg_sym = 0.5 * (seg + seg[::-1])
    out = np.zeros_like(h)
    out[a:b + 1] = seg_sym
    return out


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _sym_polish(h, deadline, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        x0 = h[:m].copy()
    else:
        x0 = h.copy()
    best_x = x0.copy()
    bestC = _C(_build_from_half(best_x, N, mode))

    stages = [('as', 1e-4), ('as', 1e-6),
              ('sm', 3000.0), ('sm', 12000.0),
              ('sm', 50000.0), ('sm', 200000.0)]
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best_x.copy(), 'bestC': bestC}

        if kind == 'as':
            def fun(x, _t=param):
                hh = _build_from_half(x, N, mode)
                cv, gfull = _active_set_obj(hh, _t)
                return cv, _sym_grad_chain(gfull, N, mode)
        else:
            def fun(x, _b=param):
                hh = _build_from_half(x, N, mode)
                J, gfull = _softmax_obj(hh, _b)
                return J, _sym_grad_chain(gfull, N, mode)

        def cb(xk):
            c = _C(_build_from_half(xk, N, mode))
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 2000, cb)
        c = _C(_build_from_half(xf, N, mode))
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best_x = state['best'].copy()
        bestC = state['bestC']

    return _build_from_half(best_x, N, mode), bestC


def _n_sweep(base, bestC, deadline, Ns):
    best = base.copy()
    n_left = max(1, len(Ns))
    for N2 in Ns:
        now = time.process_time()
        if now >= deadline:
            break
        remaining = deadline - now
        slice_deadline = now + remaining / n_left
        n_left -= 1
        h2 = _interp_to(best, N2)
        hb, cb = _polish(h2, slice_deadline,
                         [('as', 1e-4), ('as', 1e-6), ('sm', 12000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    return best, bestC


# ---------- Exact reduced Newton on active set ----------

def _half_vars(h, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        return h[:m].copy()
    return h.copy()


def _newton_active(h, deadline, mode, tol_rel=1e-9, max_iter=40, freeze_zeros=False):
    """Exact reduced Newton step on the max plateau, symmetry-constrained."""
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
    else:
        m = N

    def build(x):
        return _build_from_half(x, N, mode)

    x = _half_vars(h, mode)
    hh = build(x)
    Cval = _C(hh)
    best_x = x.copy()
    best_C = Cval

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = _conv(hh)
        M = float(conv.max())
        tol = tol_rel * M
        K = np.where(conv >= M - tol)[0]
        if K.size == 0:
            break
        ind = np.zeros(N)
        ind[K] = 1.0
        corr = np.convolve(ind, hh[::-1])
        gM = 2.0 * corr[N - 1: 2 * N - 1] / K.size
        gfull = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
        g = _sym_grad_chain(gfull, N, mode)

        nz = x > 1e-14
        gscale = np.max(np.abs(g)) + 1e-30
        resid = np.where(nz, g, np.minimum(g, 0.0))
        res_norm = np.max(np.abs(resid)) / gscale
        if res_norm < 1e-12:
            break

        Kset = np.zeros(2 * N - 1, dtype=bool)
        Kset[K] = True
        if mode == 'centered':
            pre = []
            for a in range(m):
                lst = [(a, 1.0)]
                if N % 2 == 0:
                    lst.append((N - 1 - a, 1.0))
                else:
                    if a < m - 1:
                        lst.append((N - 1 - a, 1.0))
                pre.append(lst)
        else:
            pre = []
            for a in range(m):
                lst = [(a, 0.5)]
                b = N - 1 - a
                if b != a:
                    lst.append((b, 0.5))
                pre.append(lst)

        Hr = np.zeros((m, m))
        coef_M = 2.0 * N / (S * S) * (2.0 / K.size)
        coef_g = -4.0 * N / (S * S * S)
        coef_S = 12.0 * N * M / (S * S * S * S)
        for a in range(m):
            for b in range(m):
                s = 0.0
                for (i, wi) in pre[a]:
                    for (j, wj) in pre[b]:
                        if Kset[i + j]:
                            s += wi * wj
                Hr[a, b] = coef_M * s + coef_g * (g[a] + g[b]) + coef_S
        Hr = 0.5 * (Hr + Hr.T)

        if freeze_zeros:
            fixed = (x <= 1e-14)
        else:
            fixed = (x <= 1e-14) & (g > 0)
        free = ~fixed
        dx = np.zeros(m)
        if np.any(free):
            Hf = Hr[np.ix_(free, free)]
            gf = g[free]
            tr = np.trace(Hf) / max(1, Hf.shape[0])
            reg = 1e-12 * max(abs(tr), 1e-30)
            try:
                df = np.linalg.solve(Hf + reg * np.eye(Hf.shape[0]), -gf)
            except np.linalg.LinAlgError:
                df = -gf / (np.abs(np.diag(Hf)) + 1e-12)
            dx[free] = df
        slope = float(np.dot(g, dx))
        if slope >= 0:
            dx = -g / (np.abs(np.diag(Hr)) + 1e-12)
            slope = float(np.dot(g, dx))
        if slope >= 0:
            break

        step = 1.0
        improved = False
        for _ in range(40):
            xn = x + step * dx
            xn = np.maximum(xn, 0.0)
            cn = _C(build(xn))
            if cn < Cval - 1e-16:
                x = xn
                Cval = cn
                improved = True
                if cn < best_C:
                    best_C = cn
                    best_x = xn.copy()
                break
            step *= 0.5
        if not improved:
            break

    return build(best_x), best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.9f (N=%d)" % (bestC, len(best)))

    # ===== EXPERIMENT: exact reduced Newton with free zeros, then refreeze =====
    newton_end = t0 + budget_seconds * 0.55
    best_newton = best.copy()
    best_newtonC = bestC
    for mode in ('centered', 'uncentered'):
        if time.process_time() >= newton_end:
            break
        if mode == 'centered':
            hs = _mirror_centered(best)
        else:
            hs = _mirror_uncentered(best)
        # Free zeros during Newton
        hn, cn = _newton_active(hs, newton_end, mode, tol_rel=1e-12,
                                max_iter=200, freeze_zeros=False)
        # Refreeze: zero out tiny entries, then one frozen Newton pass
        hn = hn.copy()
        hn[hn < 1e-14] = 0.0
        if time.process_time() < newton_end:
            hn2, cn2 = _newton_active(hn, newton_end, mode, tol_rel=1e-12,
                                      max_iter=200, freeze_zeros=True)
            if cn2 < cn:
                hn, cn = hn2, cn2
        if cn < best_newtonC - 1e-15:
            best_newtonC = cn
            best_newton = hn.copy()
            print("newton %s: C=%.12f" % (mode, cn))
    if best_newtonC < bestC:
        bestC = best_newtonC
        best = best_newton.copy()

    # short polish
    polish_end = t0 + budget_seconds * 0.70
    if time.process_time() < polish_end:
        hb, cb = _polish(best, polish_end, [('sm', 200000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after newton+polish: C=%.12f (N=%d)" % (bestC, len(best)))

    # ===== Original base pipeline (kept, with remaining budget) =====
    phase1_end = t0 + budget_seconds * 0.78
    if time.process_time() < phase1_end:
        hb, cb = _polish(best, phase1_end,
                         [('as', 1e-6), ('sm', 50000.0), ('sm', 200000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after polish: C=%.9f" % bestC)

    sym_end = t0 + budget_seconds * 0.86
    if time.process_time() < sym_end:
        best_sym = best.copy()
        best_symC = bestC
        for mode in ('centered', 'uncentered'):
            if time.process_time() >= sym_end:
                break
            if mode == 'centered':
                hs = _mirror_centered(best)
            else:
                hs = _mirror_uncentered(best)
            hopt, copt = _sym_polish(hs, sym_end, mode)
            if copt < best_symC - 1e-15:
                best_symC = copt
                best_sym = hopt.copy()
                print("sym %s: C=%.9f" % (mode, copt))
        if best_symC < bestC - 1e-15:
            bestC = best_symC
            best = best_sym.copy()
    print("after symmetry: C=%.9f" % bestC)

    final_end = deadline
    if time.process_time() < final_end:
        hb, cb = _polish(best, final_end,
                         [('as', 1e-8), ('sm', 800000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("final C=%.12f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 400:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: N - 1 + N]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _run_lbfgs(fun, x0, deadline, maxiter, callback):
    if time.process_time() >= deadline:
        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except StopIteration:
        return x0
    except Exception:
        return x0


def _refine_sm(h, betas, deadline):
    state = {'best': h.copy(), 'bestC': _C(h)}
    for beta in betas:
        if time.process_time() >= deadline:
            break

        def fun(x, _b=beta):
            return _softmax_obj(x, _b)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        xf = _run_lbfgs(fun, state['best'], deadline, 2000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
    return state['best'], state['bestC']


def _plateau_grad(h, rel=1e-4):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return np.zeros(N)
    conv = _conv(h)
    m = conv.max()
    thresh = m * (1.0 - rel)
    ks = np.nonzero(conv >= thresh)[0]
    if ks.size == 0:
        ks = np.array([int(np.argmax(conv))])
    C = 2.0 * N * m / (S * S)
    g = np.zeros(N)
    inv = 1.0 / ks.size
    for k in ks:
        lo = max(0, k - (N - 1))
        hi = min(N - 1, k)
        g[lo:hi + 1] += 2.0 * h[k - np.arange(lo, hi + 1)]
    g = g * (inv * (2.0 * N) * 2.0) / (S * S) - (2.0 * C) / S
    return g


def _adam_polish(h, deadline, max_iter=4000, lr=0.005):
    h = np.maximum(np.asarray(h, dtype=float), 0.0)
    N = len(h)
    if N == 0 or h.sum() <= 0:
        return h
    x = np.log(np.maximum(h, 1e-12))
    m = np.zeros(N)
    v = np.zeros(N)
    b1, b2, eps = 0.9, 0.999, 1e-8
    best = h.copy()
    bestC = _C(h)
    for t in range(1, max_iter + 1):
        if time.process_time() >= deadline:
            break
        hh = np.exp(x)
        g = _plateau_grad(hh)
        gl = g * hh
        m = b1 * m + (1 - b1) * gl
        v = b2 * v + (1 - b2) * (gl * gl)
        mhat = m / (1 - b1 ** t)
        vhat = v / (1 - b2 ** t)
        x = x - lr * mhat / (np.sqrt(vhat) + eps)
        x = np.clip(x, -30.0, 30.0)
        hh2 = np.exp(x)
        c2 = _C(hh2)
        if c2 < bestC:
            bestC = c2
            best = hh2.copy()
    return best


def _coord_polish(hh, C, deadline):
    rng = np.random.default_rng(999)
    step = 0.02
    mean = max(hh.mean(), 1e-12)
    while time.process_time() < deadline:
        improved = False
        idx = rng.permutation(len(hh))
        for i in idx:
            if time.process_time() >= deadline:
                break
            old = hh[i]
            for fac in (1.0 + step, 1.0 - step):
                hh[i] = max(0.0, old * fac)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
            for d in (step * mean, -step * mean):
                hh[i] = max(0.0, old + d)
                cc = _C(hh)
                if cc < C - 1e-16:
                    C = cc
                    old = hh[i]
                    improved = True
                else:
                    hh[i] = old
        if not improved:
            step *= 0.6
            if step < 1e-7:
                break
    return hh, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()

    if seed is None:
        x = np.linspace(-1, 1, 50)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)

    # Phase 1: softmax continuation at seed's N plus neighbors.
    base_N = len(seed)
    N_list = []
    for f in (1.0, 2.0, 0.5, 1.5, 3.0):
        n = int(round(base_N * f))
        n = max(50, min(30000, n))
        if n not in N_list:
            N_list.append(n)
    betas = [1000.0, 4000.0, 16000.0, 64000.0, 256000.0, 1e6]
    for N in N_list:
        if time.process_time() >= deadline:
            break
        h = _interp_to(best, N)
        if h.sum() <= 0:
            continue
        h = h / max(h.max(), 1e-12)
        hb, hc = _refine_sm(h, betas, deadline)
        if hc < bestC:
            bestC = hc
            best = hb.copy()

    # Phase 2: Adam in log-space with plateau-averaged subgradient.
    if time.process_time() < deadline:
        polished = _adam_polish(best, deadline, max_iter=4000, lr=0.004)
        cp = _C(polished)
        if cp < bestC:
            bestC = cp
            best = polished.copy()

    # Phase 3: coordinate polish on exact C.
    if time.process_time() < deadline:
        hh, C = _coord_polish(best.copy(), bestC, deadline)
        if C < bestC:
            bestC = C
            best = hh.copy()

    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 400:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _run_lbfgs(fun, x0, deadline, maxiter, callback):
    if time.process_time() >= deadline:
        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _polish(h, deadline, stages):
    best = h.copy()
    bestC = _C(h)
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        if kind == 'sm':
            def fun(x, _b=param):
                return _softmax_obj(x, _b)
        else:
            def fun(x, _t=param):
                return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 3000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _sym_polish(h, deadline, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        x0 = h[:m].copy()
    else:
        x0 = h.copy()
    best_x = x0.copy()
    bestC = _C(_build_from_half(best_x, N, mode))

    stages = [('as', 1e-6),
              ('sm', 12000.0),
              ('sm', 50000.0), ('sm', 200000.0)]
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best_x.copy(), 'bestC': bestC}

        if kind == 'as':
            def fun(x, _t=param):
                hh = _build_from_half(x, N, mode)
                cv, gfull = _active_set_obj(hh, _t)
                return cv, _sym_grad_chain(gfull, N, mode)
        else:
            def fun(x, _b=param):
                hh = _build_from_half(x, N, mode)
                J, gfull = _softmax_obj(hh, _b)
                return J, _sym_grad_chain(gfull, N, mode)

        def cb(xk):
            c = _C(_build_from_half(xk, N, mode))
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 2000, cb)
        c = _C(_build_from_half(xf, N, mode))
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best_x = state['best'].copy()
        bestC = state['bestC']

    return _build_from_half(best_x, N, mode), bestC


def _half_vars(h, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        return h[:m].copy()
    return h.copy()


def _newton_active(h, deadline, mode, tol_rel=1e-11, max_iter=200):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
    else:
        m = N

    def build(x):
        return _build_from_half(x, N, mode)

    x = _half_vars(h, mode)
    hh = build(x)
    Cval = _C(hh)
    best_x = x.copy()
    best_C = Cval

    if mode == 'centered':
        pairs = []
        for a in range(m):
            lst = [(a, 1.0)]
            if N % 2 == 0:
                lst.append((N - 1 - a, 1.0))
            elif a < m - 1:
                lst.append((N - 1 - a, 1.0))
            pairs.append(lst)
    else:
        pairs = []
        for a in range(m):
            b = N - 1 - a
            if b == a:
                pairs.append([(a, 1.0)])
            else:
                pairs.append([(a, 0.5), (b, 0.5)])

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = _conv(hh)
        M = float(conv.max())
        tol = tol_rel * M
        K = np.where(conv >= M - tol)[0]
        if K.size == 0:
            break
        ind = np.zeros(N)
        ind[K] = 1.0
        corr = np.convolve(ind, hh[::-1])
        gM = 2.0 * corr[N - 1: 2 * N - 1] / K.size
        gfull = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
        g = _sym_grad_chain(gfull, N, mode)

        nz = x > 1e-14
        gscale = np.max(np.abs(g)) + 1e-30
        resid = np.where(nz, g, np.minimum(g, 0.0))
        if np.max(np.abs(resid)) / gscale < 1e-12:
            break

        Kset = np.zeros(2 * N - 1, dtype=bool)
        Kset[K] = True
        coef_M = 2.0 * N / (S * S) * (2.0 / K.size)
        coef_g = -4.0 * N / (S * S * S)
        coef_S = 12.0 * N * M / (S * S * S * S)

        # Build Hr using symmetry expansion
        Hr = np.empty((m, m))
        gsum = g[:, None] + g[None, :]
        for a in range(m):
            row = np.zeros(2 * N - 1)
            for (i, wi) in pairs[a]:
                row[i] += wi
            for b in range(m):
                s = 0.0
                for (j, wj) in pairs[b]:
                    if Kset[a_row_offset(a, j, pairs, N)]:
                        pass
            # fallback simple
            acc = np.zeros(m)
            for b in range(m):
                s = 0.0
                for (i, wi) in pairs[a]:
                    for (j, wj) in pairs[b]:
                        if Kset[i + j]:
                            s += wi * wj
                acc[b] = s
            Hr[a, :] = coef_M * acc + coef_g * gsum[a, :] + coef_S
        Hr = 0.5 * (Hr + Hr.T)

        fixed = (x <= 1e-14) & (g > 0)
        free = ~fixed
        dx = np.zeros(m)
        if np.any(free):
            Hf = Hr[np.ix_(free, free)]
            gf = g[free]
            tr = np.trace(Hf) / max(1, Hf.shape[0])
            reg = 1e-12 * max(abs(tr), 1e-30)
            try:
                df = np.linalg.solve(Hf + reg * np.eye(Hf.shape[0]), -gf)
            except np.linalg.LinAlgError:
                df = -gf / (np.abs(np.diag(Hf)) + 1e-12)
            dx[free] = df
        slope = float(np.dot(g, dx))
        if slope >= 0:
            dx = -g / (np.abs(np.diag(Hr)) + 1e-12)
            slope = float(np.dot(g, dx))
        if slope >= 0:
            break

        step = 1.0
        improved = False
        for _ in range(40):
            xn = x + step * dx
            xn = np.maximum(xn, 0.0)
            cn = _C(build(xn))
            if cn < Cval - 1e-16:
                x = xn
                Cval = cn
                improved = True
                if cn < best_C:
                    best_C = cn
                    best_x = xn.copy()
                break
            step *= 0.5
        if not improved:
            break

    return build(best_x), best_C


def a_row_offset(a, j, pairs, N):
    return 0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.9f (N=%d)" % (bestC, len(best)))

    # Phase 1: polish current solution
    phase1_end = t0 + budget_seconds * 0.28
    hb, cb = _polish(best, phase1_end,
                     [('as', 1e-6),
                      ('sm', 12000.0), ('sm', 50000.0), ('sm', 200000.0)])
    if cb < bestC:
        bestC = cb
        best = hb.copy()
    print("after polish: C=%.9f" % bestC)

    # Phase 2: symmetry optimization
    sym_end = t0 + budget_seconds * 0.50
    if time.process_time() < sym_end:
        best_sym = best.copy()
        best_symC = bestC
        for mode in ('centered', 'uncentered'):
            if time.process_time() >= sym_end:
                break
            if mode == 'centered':
                hs = _mirror_centered(best)
            else:
                hs = best.copy()
            hopt, copt = _sym_polish(hs, sym_end, mode)
            if copt < best_symC - 1e-15:
                best_symC = copt
                best_sym = hopt.copy()
                print("sym %s: C=%.9f" % (mode, copt))
        if best_symC < bestC - 1e-15:
            bestC = best_symC
            best = best_sym.copy()
    print("after symmetry: C=%.9f" % bestC)

    # Phase 3: exact reduced Newton on active set
    newton_end = t0 + budget_seconds * 0.72
    best_newton = best.copy()
    best_newtonC = bestC
    for mode in ('centered', 'uncentered'):
        if time.process_time() >= newton_end:
            break
        if mode == 'centered':
            hs = _mirror_centered(best)
        else:
            hs = best.copy()
        hn, cn = _newton_active(hs, newton_end, mode, tol_rel=1e-11)
        if cn < best_newtonC - 1e-15:
            best_newtonC = cn
            best_newton = hn.copy()
            print("newton %s: C=%.12f" % (mode, cn))
    if best_newtonC < bestC:
        bestC = best_newtonC
        best = best_newton.copy()

    # Phase 4: N sweep
    Nc = len(best)
    Ns = []
    for d in [0, -1, 1, -2, 2, -3, 3]:
        N2 = Nc + d
        if 1 <= N2 <= 30000 and N2 not in Ns:
            Ns.append(N2)
    Ns.sort(key=lambda x: abs(x - Nc))
    sweep_end = t0 + budget_seconds * 0.82
    n_left = max(1, len(Ns))
    for N2 in Ns:
        now = time.process_time()
        if now >= sweep_end:
            break
        remaining = sweep_end - now
        slice_deadline = now + remaining / n_left
        n_left -= 1
        h2 = _interp_to(best, N2)
        hb, cb = _polish(h2, slice_deadline,
                         [('as', 1e-6), ('sm', 12000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after N sweep: C=%.9f (N=%d)" % (bestC, len(best)))

    # Phase 5: final polish
    final_end = deadline
    if time.process_time() < final_end:
        hb, cb = _polish(best, final_end,
                         [('as', 1e-8), ('sm', 800000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()

    print("final C=%.12f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 400:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _run_lbfgs(fun, x0, deadline, maxiter, callback):
    if time.process_time() >= deadline:
        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _polish(h, deadline, stages):
    best = h.copy()
    bestC = _C(h)
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        if kind == 'sm':
            def fun(x, _b=param):
                return _softmax_obj(x, _b)
        else:
            def fun(x, _t=param):
                return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 3000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _mirror_uncentered(h):
    nz = np.where(h > 0)[0]
    if nz.size == 0:
        return h.copy()
    a, b = nz[0], nz[-1]
    seg = h[a:b + 1]
    seg_sym = 0.5 * (seg + seg[::-1])
    out = np.zeros_like(h)
    out[a:b + 1] = seg_sym
    return out


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _sym_polish(h, deadline, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        x0 = h[:m].copy()
    else:
        x0 = h.copy()
    best_x = x0.copy()
    bestC = _C(_build_from_half(best_x, N, mode))

    stages = [('as', 1e-6),
              ('sm', 12000.0),
              ('sm', 50000.0), ('sm', 200000.0)]
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best_x.copy(), 'bestC': bestC}

        if kind == 'as':
            def fun(x, _t=param):
                hh = _build_from_half(x, N, mode)
                cv, gfull = _active_set_obj(hh, _t)
                return cv, _sym_grad_chain(gfull, N, mode)
        else:
            def fun(x, _b=param):
                hh = _build_from_half(x, N, mode)
                J, gfull = _softmax_obj(hh, _b)
                return J, _sym_grad_chain(gfull, N, mode)

        def cb(xk):
            c = _C(_build_from_half(xk, N, mode))
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 2000, cb)
        c = _C(_build_from_half(xf, N, mode))
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best_x = state['best'].copy()
        bestC = state['bestC']

    return _build_from_half(best_x, N, mode), bestC


# ---------- Vectorized exact reduced Newton on active set ----------

def _newton_active(h, deadline, mode, tol_rel=1e-11, max_iter=200):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
    else:
        m = N

    def build(x):
        return _build_from_half(x, N, mode)

    x = _half_vars(h, mode)
    hh = build(x)
    Cval = _C(hh)
    best_x = x.copy()
    best_C = Cval

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = _conv(hh)
        M = float(conv.max())
        tol = tol_rel * M
        K = np.where(conv >= M - tol)[0]
        if K.size == 0:
            break
        ind = np.zeros(N)
        ind[K] = 1.0
        corr = np.convolve(ind, hh[::-1])
        gM = 2.0 * corr[N - 1: 2 * N - 1] / K.size
        gfull = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
        g = _sym_grad_chain(gfull, N, mode)

        nz = x > 1e-14
        gscale = np.max(np.abs(g)) + 1e-30
        resid = np.where(nz, g, np.minimum(g, 0.0))
        if np.max(np.abs(resid)) / gscale < 1e-13:
            break

        if mode == 'centered':
            idxA = []
            wA = []
            for a in range(m):
                idxA.append(a); wA.append(1.0)
                if N % 2 == 0:
                    idxA.append(N - 1 - a); wA.append(1.0)
                elif a < m - 1:
                    idxA.append(N - 1 - a); wA.append(1.0)
        else:
            idxA = []
            wA = []
            for a in range(m):
                idxA.append(a); wA.append(0.5)
                b = N - 1 - a
                if b != a:
                    idxA.append(b); wA.append(0.5)
        idxA = np.array(idxA, dtype=np.int64)
        wA = np.array(wA, dtype=float)
        counts = np.array([1 + (1 if (N % 2 == 0 or (mode == 'centered' and a < m - 1)) else 0)
                           if mode == 'centered' else (1 if a == N - 1 - a else 2)
                           for a in range(m)])
        offs = np.zeros(m + 1, dtype=np.int64)
        offs[1:] = np.cumsum(counts)

        Kset = np.zeros(2 * N - 1, dtype=bool)
        Kset[K] = True

        coef_M = 2.0 * N / (S * S) * (2.0 / K.size)
        coef_g = -4.0 * N / (S * S * S)
        coef_S = 12.0 * N * M / (S * S * S * S)

        Hr = np.empty((m, m))
        gsum = g[:, None] + g[None, :]
        for a in range(m):
            ia = idxA[offs[a]:offs[a + 1]]
            wa = wA[offs[a]:offs[a + 1]]
            acc = np.zeros(m)
            for ii, wi in zip(ia, wa):
                jj = ii + idxA
                contrib = Kset[jj] * wA
                csum = np.zeros(m)
                for b in range(m):
                    csum[b] = contrib[offs[b]:offs[b + 1]].sum()
                acc += wi * csum
            Hr[a, :] = coef_M * acc + coef_g * gsum[a, :] + coef_S
        Hr = 0.5 * (Hr + Hr.T)

        fixed = (x <= 1e-14) & (g > 0)
        free = ~fixed
        dx = np.zeros(m)
        if np.any(free):
            Hf = Hr[np.ix_(free, free)]
            gf = g[free]
            tr = np.trace(Hf) / max(1, Hf.shape[0])
            reg = 1e-13 * max(abs(tr), 1e-30)
            try:
                df = np.linalg.solve(Hf + reg * np.eye(Hf.shape[0]), -gf)
            except np.linalg.LinAlgError:
                df = -gf / (np.abs(np.diag(Hf)) + 1e-12)
            dx[free] = df
        slope = float(np.dot(g, dx))
        if slope >= 0:
            dx = -g / (np.abs(np.diag(Hr)) + 1e-12)
            slope = float(np.dot(g, dx))
        if slope >= 0:
            break

        step = 1.0
        improved = False
        for _ in range(50):
            xn = np.maximum(x + step * dx, 0.0)
            cn = _C(build(xn))
            if cn < Cval - 1e-16:
                x = xn
                Cval = cn
                improved = True
                if cn < best_C:
                    best_C = cn
                    best_x = xn.copy()
                break
            step *= 0.5
        if not improved:
            break

    return build(best_x), best_C


def _half_vars(h, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        return h[:m].copy()
    return h.copy()


def _perturb_candidates(h, rng):
    """Build 10 perturbed candidates from h."""
    N = len(h)
    x = np.linspace(0.0, 1.0, N)
    hmax = float(h.max()) if h.size else 1.0
    cands = []
    # 5 multiplicative sine perturbations
    for k in range(1, 6):
        phi = rng.uniform(0, 2 * np.pi)
        factor = 1.0 + 0.002 * np.sin(np.pi * k * x + phi)
        cands.append(np.maximum(h * factor, 0.0))
    # 5 additive smooth random cosine series
    for _ in range(5):
        ncomp = 4
        s = np.zeros(N)
        for j in range(1, ncomp + 1):
            amp = rng.uniform(-1.0, 1.0)
            phi = rng.uniform(0, 2 * np.pi)
            s += amp * np.cos(np.pi * j * x + phi)
        s = s / (np.max(np.abs(s)) + 1e-30)
        cands.append(np.maximum(h + 0.001 * hmax * s, 0.0))
    return cands


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.12f (N=%d)" % (bestC, len(best)))

    rng = np.random.default_rng(12345)

    # --- Perturbation exploration phase ---
    perturb_end = t0 + budget_seconds * 0.35
    if time.process_time() < perturb_end:
        cands = _perturb_candidates(best, rng)
        best_pert = best.copy()
        best_pertC = bestC
        for idx, c in enumerate(cands):
            if time.process_time() >= perturb_end:
                break
            hs = _mirror_centered(c)
            hn, cn = _newton_active(hs, perturb_end, 'centered',
                                    tol_rel=1e-9, max_iter=30)
            if cn < best_pertC - 1e-15:
                best_pertC = cn
                best_pert = hn.copy()
                print("perturb %d: C=%.12f" % (idx, cn))
        if best_pertC < bestC - 1e-15:
            bestC = best_pertC
            best = best_pert.copy()
            print("perturb best: C=%.12f" % bestC)

    # Newton phase: exact reduced Newton with symmetry, tight tol.
    newton_end = t0 + budget_seconds * 0.60
    for mode in ('centered', 'uncentered'):
        if time.process_time() >= newton_end:
            break
        if mode == 'centered':
            hs = _mirror_centered(best)
        else:
            hs = _mirror_uncentered(best)
        hn, cn = _newton_active(hs, newton_end, mode, tol_rel=1e-11, max_iter=200)
        if cn < bestC - 1e-15:
            bestC = cn
            best = hn.copy()
            print("newton %s: C=%.12f" % (mode, cn))

    # Polish
    polish_end = t0 + budget_seconds * 0.72
    if time.process_time() < polish_end:
        hb, cb = _polish(best, polish_end, [('sm', 200000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("after polish: C=%.12f (N=%d)" % (bestC, len(best)))

    # Symmetry polish
    sym_end = t0 + budget_seconds * 0.85
    if time.process_time() < sym_end:
        for mode in ('centered', 'uncentered'):
            if time.process_time() >= sym_end:
                break
            if mode == 'centered':
                hs = _mirror_centered(best)
            else:
                hs = _mirror_uncentered(best)
            hopt, copt = _sym_polish(hs, sym_end, mode)
            if copt < bestC - 1e-15:
                bestC = copt
                best = hopt.copy()
                print("sym %s: C=%.12f" % (mode, copt))
    print("after symmetry: C=%.12f" % bestC)

    final_end = deadline
    if time.process_time() < final_end:
        hb, cb = _polish(best, final_end,
                         [('as', 1e-8), ('sm', 800000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("final C=%.12f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
try:
    from scipy.signal import fftconvolve
except Exception:
    fftconvolve = None


def _conv(h):
    if fftconvolve is not None and len(h) > 400:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _interp_to(h, N):
    M = len(h)
    if M == N:
        return h.astype(float).copy()
    xp = np.linspace(0.0, 1.0, M)
    x = np.linspace(0.0, 1.0, N)
    return np.interp(x, xp, h).astype(float)


def _softmax_obj(h, beta):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    z = beta * conv
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    logZ = zmax + np.log(Z)
    J = logZ / (beta * S * S)
    p = e / Z
    corr = np.convolve(p, h[::-1])
    grad_conv = 2.0 * corr[N - 1: 2 * N - 1]
    grad = grad_conv / (S * S) - 2.0 * J / S
    return J, grad


def _run_lbfgs(fun, x0, deadline, maxiter, callback):
    if time.process_time() >= deadline:
        return x0
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0), callback=callback,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 10,
                                'ftol': 1e-16, 'gtol': 1e-14})
        return res.x
    except Exception:
        return x0


def _polish(h, deadline, stages):
    best = h.copy()
    bestC = _C(h)
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
        state = {'best': best.copy(), 'bestC': bestC}

        if kind == 'sm':
            def fun(x, _b=param):
                return _softmax_obj(x, _b)
        else:
            def fun(x, _t=param):
                return _active_set_obj(x, _t)

        def cb(xk):
            c = _C(xk)
            if c < state['bestC']:
                state['bestC'] = c
                state['best'] = xk.copy()

        xf = _run_lbfgs(fun, state['best'], deadline, 3000, cb)
        c = _C(xf)
        if c < state['bestC']:
            state['bestC'] = c
            state['best'] = xf.copy()
        best = state['best'].copy()
        bestC = state['bestC']
    return best, bestC


def _active_set_obj(h, tol_rel=1e-6):
    N = len(h)
    S = h.sum()
    if S <= 0:
        return 1e18, np.zeros(N)
    conv = _conv(h)
    M = float(conv.max())
    tol = tol_rel * M
    K = np.where(conv >= M - tol)[0]
    Cval = 2.0 * N * M / (S * S)
    ind = np.zeros(N)
    ind[K] = 1.0
    corr = np.convolve(ind, h[::-1])
    gM = 2.0 * corr[N - 1: 2 * N - 1] / len(K)
    grad = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
    return Cval, grad


def _build_from_half(x, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        h = np.zeros(N)
        h[:m] = x[:m]
        if N % 2 == 0:
            h[m:] = x[:m][::-1]
        else:
            h[m:] = x[:m - 1][::-1]
        return h
    else:
        return 0.5 * (x + x[::-1])


def _mirror_centered(h):
    return 0.5 * (h + h[::-1])


def _mirror_uncentered(h):
    nz = np.where(h > 0)[0]
    if nz.size == 0:
        return h.copy()
    a, b = nz[0], nz[-1]
    seg = h[a:b + 1]
    seg_sym = 0.5 * (seg + seg[::-1])
    out = np.zeros_like(h)
    out[a:b + 1] = seg_sym
    return out


def _sym_grad_chain(gfull, N, mode):
    if mode == 'centered':
        m = (N + 1) // 2
        g = gfull[:m].copy()
        if N % 2 == 0:
            g = g + gfull[m:][::-1]
        else:
            g[:m - 1] += gfull[m:][::-1]
        return g
    else:
        return 0.5 * (gfull + gfull[::-1])


def _half_vars(h, mode):
    N = len(h)
    if mode == 'centered':
        m = (N + 1) // 2
        return h[:m].copy()
    return h.copy()


def _build_W(N, mode):
    """Symmetry expansion matrix W (N x m): h_full = W @ x."""
    if mode == 'centered':
        m = (N + 1) // 2
        W = np.zeros((N, m))
        for a in range(m):
            W[a, a] = 1.0
            if N % 2 == 0:
                W[N - 1 - a, a] = 1.0
            elif a < m - 1:
                W[N - 1 - a, a] = 1.0
        return W
    else:
        m = N
        W = np.zeros((N, m))
        for a in range(m):
            W[a, a] = 0.5
            W[N - 1 - a, a] = 0.5
        return W


def _newton_active_blas(h, deadline, mode, W, tol_rel=1e-11, max_iter=60):
    N = len(h)
    m = W.shape[1]

    def build(x):
        return _build_from_half(x, N, mode)

    x = _half_vars(h, mode)
    hh = build(x)
    Cval = _C(hh)
    best_x = x.copy()
    best_C = Cval

    for it in range(max_iter):
        if time.process_time() >= deadline:
            break
        hh = build(x)
        S = hh.sum()
        if S <= 0:
            break
        conv = _conv(hh)
        M = float(conv.max())
        tol = tol_rel * M
        K = np.where(conv >= M - tol)[0]
        if K.size == 0:
            break
        ind = np.zeros(N)
        ind[K] = 1.0
        corr = np.convolve(ind, hh[::-1])
        gM = 2.0 * corr[N - 1: 2 * N - 1] / K.size
        gfull = (2.0 * N / (S * S)) * gM - (4.0 * N * M) / (S * S * S)
        g = _sym_grad_chain(gfull, N, mode)

        nz = x > 1e-14
        gscale = np.max(np.abs(g)) + 1e-30
        resid = np.where(nz, g, np.minimum(g, 0.0))
        if np.max(np.abs(resid)) / gscale < 1e-13:
            break

        Kset = np.zeros(2 * N - 1, dtype=float)
        Kset[K] = 1.0

        # Q[i,j] = Kset[i+j]
        idx = np.arange(N)
        Q = Kset[idx[:, None] + idx[None, :]]

        coef_M = 2.0 * N / (S * S) * (2.0 / K.size)
        coef_g = -4.0 * N / (S * S * S)
        coef_S = 12.0 * N * M / (S * S * S * S)

        WQW = W.T @ Q @ W
        Hr = coef_M * WQW + coef_g * (g[:, None] + g[None, :]) + coef_S
        Hr = 0.5 * (Hr + Hr.T)

        fixed = (x <= 1e-14) & (g > 0)
        free = ~fixed
        dx = np.zeros(m)
        if np.any(free):
            Hf = Hr[np.ix_(free, free)]
            gf = g[free]
            tr = np.trace(Hf) / max(1, Hf.shape[0])
            reg = 1e-13 * max(abs(tr), 1e-30)
            try:
                df = np.linalg.solve(Hf + reg * np.eye(Hf.shape[0]), -gf)
            except np.linalg.LinAlgError:
                df = -gf / (np.abs(np.diag(Hf)) + 1e-12)
            dx[free] = df
        slope = float(np.dot(g, dx))
        if slope >= 0:
            dx = -g / (np.abs(np.diag(Hr)) + 1e-12)
            slope = float(np.dot(g, dx))
        if slope >= 0:
            break

        step = 1.0
        improved = False
        for _ in range(50):
            xn = np.maximum(x + step * dx, 0.0)
            cn = _C(build(xn))
            if cn < Cval - 1e-16:
                x = xn
                Cval = cn
                improved = True
                if cn < best_C:
                    best_C = cn
                    best_x = xn.copy()
                break
            step *= 0.5
        if not improved:
            break

    return build(best_x), best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    seed = None
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            seed = s.copy()
    if seed is None:
        N0 = 60
        x = np.linspace(-1, 1, N0)
        seed = np.maximum(0.0, 1.0 - np.abs(x)) + 0.05

    best = seed.copy()
    bestC = _C(best)
    print("start C=%.12f (N=%d)" % (bestC, len(best)))

    # Refinement at larger N: interpolate start, run BLAS Newton, then softmax polish.
    refine_end = t0 + budget_seconds * 0.85
    for Nnew in (2360, 4720):
        if time.process_time() >= refine_end:
            break
        hN = _interp_to(best, Nnew)
        cN = _C(hN)
        print("interp N=%d: C=%.12f" % (Nnew, cN))
        if cN < bestC:
            bestC = cN
            best = hN.copy()

        for mode in ('centered', 'uncentered'):
            if time.process_time() >= refine_end:
                break
            if mode == 'centered':
                hs = _mirror_centered(best)
            else:
                hs = _mirror_uncentered(best)
            W = _build_W(Nnew, mode)
            hn, cn = _newton_active_blas(hs, refine_end, mode, W,
                                         tol_rel=1e-11, max_iter=60)
            if cn < bestC - 1e-15:
                bestC = cn
                best = hn.copy()
                print("newton %s N=%d: C=%.12f" % (mode, Nnew, cn))

        if time.process_time() < refine_end:
            hb, cb = _polish(best, refine_end, [('sm', 200000.0)])
            if cb < bestC:
                bestC = cb
                best = hb.copy()
                print("polish N=%d: C=%.12f" % (Nnew, bestC))

    # Final polish at current N
    final_end = deadline
    if time.process_time() < final_end:
        hb, cb = _polish(best, final_end,
                         [('as', 1e-8), ('sm', 800000.0)])
        if cb < bestC:
            bestC = cb
            best = hb.copy()
    print("final C=%.12f (N=%d)" % (bestC, len(best)))
    return np.asarray(best, dtype=float)

