    if mode == 'centered':
        m = (N + 1) // 2
        x0 = h[:m].copy()
    else:
        x0 = h.copy()
    best_x = x0.copy()
    bestC = _C(_build_from_half(best_x, N, mode))

    stages = [('as', 1e-6),
              ('sm', 12000.0),
              ('sm', 50000.0), ('sm', 200000.0)]
    for kind, param in stages:
        if time.process_time() >= deadline:
            break
